    // Crash reports: the one-time ask (CrashReports)
    "CRASH REPORTS?" to Tr(ja = "クラッシュ レポート？", fr = "RAPPORTS DE PLANTAGE ?", de = "ABSTURZBERICHTE?", it = "SEGNALAZIONI CRASH?", es = "¿INFORMES DE FALLOS?", br = "RELATÓRIOS DE FALHAS?", pt = "RELATÓRIOS DE FALHAS?", ko = "오류 보고를 보낼까요?"),
    "When PokéDaisy crashes, it can send a report so the bug gets fixed sooner: the device model, Android version and where the app crashed. Never your ROMs, saves or anything personal. You can change this any time in Settings." to Tr(ja = "PokéDaisyが とまったとき、レポートを おくれます。バグが はやく なおります：きしゅ、Androidの バージョン、とまった ばしょ。ROMや セーブ、こじんの じょうほうは おくりません。せっていで いつでも かえられます。", fr = "Quand PokéDaisy plante, il peut envoyer un rapport pour que le bug soit corrigé plus vite : le modèle de l'appareil, la version d'Android et l'endroit du plantage. Jamais vos ROM, vos sauvegardes ni rien de personnel. Modifiable à tout moment dans les Options.", de = "Wenn PokéDaisy abstürzt, kann es einen Bericht senden, damit der Fehler schneller behoben wird: Gerätemodell, Android-Version und die Absturzstelle. Nie deine ROMs, Spielstände oder Persönliches. Jederzeit in den Optionen änderbar.", it = "Quando PokéDaisy si blocca, può inviare una segnalazione per correggere prima il bug: modello del dispositivo, versione di Android e punto del crash. Mai le tue ROM, i salvataggi o dati personali. Puoi cambiarlo quando vuoi nelle Opzioni.", es = "Cuando PokéDaisy falla, puede enviar un informe para que el error se corrija antes: el modelo del dispositivo, la versión de Android y dónde falló. Nunca tus ROM, partidas ni nada personal. Puedes cambiarlo cuando quieras en Ajustes.", br = "Quando o PokéDaisy trava, ele pode enviar um relatório para o bug ser corrigido mais rápido: o modelo do aparelho, a versão do Android e onde o app travou. Nunca suas ROMs, saves ou nada pessoal. Você pode mudar isso a qualquer momento nas Configurações.", pt = "Quando o PokéDaisy falha, pode enviar um relatório para o erro ser corrigido mais depressa: o modelo do dispositivo, a versão do Android e onde a app falhou. Nunca as suas ROMs, gravações nem nada pessoal. Pode mudar isto a qualquer momento nas Definições.", ko = "PokéDaisy가 멈추면 버그를 더 빨리 고칠 수 있도록 보고서를 보낼 수 있어요. 기기 모델, Android 버전, 앱이 멈춘 곳만 보내요. ROM, 세이브, 개인 정보는 절대 보내지 않아요. 설정에서 언제든 바꿀 수 있어요."),
    "SEND REPORTS" to Tr(ja = "おくる", fr = "ENVOYER", de = "SENDEN", it = "INVIA", es = "ENVIAR", br = "ENVIAR", pt = "ENVIAR", ko = "보고서 보내기"),

