    // The support window (SupportWindow), once after hours of play
    "ENJOYING POKéDAISY?" to Tr(ja = "PokéDaisyは たのしい?", fr = "POKéDAISY VOUS PLAÎT ?", de = "GEFÄLLT DIR POKéDAISY?", it = "TI PIACE POKéDAISY?", es = "¿TE GUSTA POKéDAISY?", br = "CURTINDO O POKéDAISY?", pt = "A GOSTAR DO POKéDAISY?", ko = "PokéDaisy 재미있나요?"),
    "Thank you for playing!" to Tr(ja = "あそんでくれて ありがとう!", fr = "Merci de jouer !", de = "Danke fürs Spielen!", it = "Grazie per giocare!", es = "¡Gracias por jugar!", br = "Obrigado por jogar!", pt = "Obrigado por jogar!", ko = "플레이해 주셔서 고마워요!"),
    "PokéDaisy is free, has no ads and is made by one person in their spare time. If it has made your games better and you'd like to see it grow, with more games and more features, a small tip goes a long way." to Tr(ja = "PokéDaisyは むりょうで こうこくも なく ひとりが あいた じかんに つくって います。 ゲームが もっと たのしく なったなら そして もっと たくさんの ゲームや きのうで そだって ほしいなら すこしの きふが おおきな ちからに なります。", fr = "PokéDaisy est gratuit, sans pub, et fait par une seule personne sur son temps libre. S'il a rendu vos jeux meilleurs et que vous voulez le voir grandir, avec plus de jeux et de fonctions, un petit don aide beaucoup.", de = "PokéDaisy ist kostenlos, ohne Werbung und wird von einer Person in ihrer Freizeit gemacht. Wenn es deine Spiele besser gemacht hat und du es wachsen sehen willst, mit mehr Spielen und Funktionen, hilft ein kleines Trinkgeld sehr.", it = "PokéDaisy è gratis, senza pubblicità e fatto da una sola persona nel tempo libero. Se ha reso migliori i tuoi giochi e vuoi vederlo crescere, con più giochi e funzioni, una piccola mancia aiuta molto.", es = "PokéDaisy es gratis, no tiene anuncios y lo hace una sola persona en su tiempo libre. Si ha mejorado tus juegos y quieres verlo crecer, con más juegos y funciones, una pequeña propina ayuda mucho.", br = "O PokéDaisy é grátis, não tem anúncios e é feito por uma só pessoa no tempo livre. Se ele deixou seus jogos melhores e você quer vê-lo crescer, com mais jogos e recursos, uma pequena gorjeta ajuda muito.", pt = "O PokéDaisy é gratuito, não tem anúncios e é feito por uma só pessoa nos tempos livres. Se tornou os seus jogos melhores e quer vê-lo crescer, com mais jogos e funções, uma pequena gorjeta ajuda muito.", ko = "PokéDaisy는 무료이고 광고가 없으며, 한 사람이 여가 시간에 만들고 있어요. 게임이 더 즐거워졌고 더 많은 게임과 기능으로 커 가길 바란다면, 작은 후원이 큰 힘이 돼요."),
    "Free, no ads, made by one person. A small tip helps PokéDaisy grow." to Tr(ja = "むりょうで こうこく なし ひとりで つくって います。 すこしの きふで PokéDaisyが そだちます。", fr = "Gratuit, sans pub, fait par une personne. Un petit don aide PokéDaisy à grandir.", de = "Kostenlos, ohne Werbung, von einer Person. Ein kleines Trinkgeld lässt PokéDaisy wachsen.", it = "Gratis, senza pubblicità, fatto da una persona. Una piccola mancia fa crescere PokéDaisy.", es = "Gratis, sin anuncios, hecho por una persona. Una pequeña propina ayuda a PokéDaisy a crecer.", br = "Grátis, sem anúncios, feito por uma pessoa. Uma pequena gorjeta ajuda o PokéDaisy a crescer.", pt = "Gratuito, sem anúncios, feito por uma pessoa. Uma pequena gorjeta ajuda o PokéDaisy a crescer.", ko = "무료, 광고 없음, 한 사람이 만들어요. 작은 후원이 PokéDaisy를 키워요."),
    "REMIND ME LATER" to Tr(ja = "あとで おしえて", fr = "PLUS TARD", de = "SPÄTER ERINNERN", it = "RICORDAMELO DOPO", es = "RECUÉRDAMELO", br = "LEMBRAR DEPOIS", pt = "LEMBRAR MAIS TARDE", ko = "나중에 알림"),
