    "PokeDaisy can't read {0} - allow All files access, then launch again" to Tr(ja = "PokeDaisyは {0}を よめません - 「すべての ファイルへの アクセス」を きょかして もういちど ひらいてください", fr = "PokeDaisy ne peut pas lire {0} - autorisez l'accès à tous les fichiers, puis relancez", de = "PokeDaisy kann {0} nicht lesen - erlaube den Zugriff auf alle Dateien und starte neu", it = "PokeDaisy non può leggere {0} - consenti l'accesso a tutti i file, poi riavvia", es = "PokeDaisy no puede leer {0} - permite el acceso a todos los archivos y vuelve a abrirlo", br = "O PokeDaisy não consegue ler {0} - permita o acesso a todos os arquivos e abra de novo", pt = "O PokeDaisy não consegue ler {0} - permita o acesso a todos os ficheiros e abra de novo", ko = "PokeDaisy가 읽을 수 없어요: {0}. 모든 파일 접근을 허용하고 다시 실행하세요"),
    "PokeDaisy can't read {0}" to Tr(ja = "PokeDaisyは {0}を よめません", fr = "PokeDaisy ne peut pas lire {0}", de = "PokeDaisy kann {0} nicht lesen", it = "PokeDaisy non può leggere {0}", es = "PokeDaisy no puede leer {0}", br = "O PokeDaisy não consegue ler {0}", pt = "O PokeDaisy não consegue ler {0}", ko = "PokeDaisy가 읽을 수 없어요: {0}"),
    "No ROM found. Put a .gba (or .zip / .7z) in {0}" to Tr(ja = "ROMが ありません。 .gba (または .zip / .7z)を {0} に いれてください", fr = "Aucune ROM trouvée. Placez un .gba (ou .zip / .7z) dans {0}", de = "Kein ROM gefunden. Lege eine .gba (oder .zip / .7z) in {0}", it = "Nessuna ROM trovata. Metti un .gba (o .zip / .7z) in {0}", es = "No se encontró ninguna ROM. Pon un .gba (o .zip / .7z) en {0}", br = "Nenhuma ROM encontrada. Coloque um .gba (ou .zip / .7z) em {0}", pt = "Nenhuma ROM encontrada. Coloque um .gba (ou .zip / .7z) em {0}", ko = "ROM을 찾지 못했어요. .gba (또는 .zip / .7z)를 여기에 넣으세요: {0}"),
    "Saved slot {0}" to Tr(ja = "スロット {0}に ほぞんしました", fr = "État enregistré ({0})", de = "In Slot {0} gespeichert", it = "Salvato nello slot {0}", es = "Guardado en la ranura {0}", br = "Salvo no espaço {0}", pt = "Guardado no espaço {0}", ko = "슬롯 {0}에 저장했어요"),
    "Slot {0}: save failed" to Tr(ja = "スロット {0}: ほぞん しっぱい", fr = "Emplacement {0} : échec", de = "Slot {0}: Speichern fehlgeschlagen", it = "Slot {0}: salvataggio non riuscito", es = "Ranura {0}: no se pudo guardar", br = "Espaço {0}: falha ao salvar", pt = "Espaço {0}: falha ao guardar", ko = "슬롯 {0}: 저장 실패"),
    "Loaded slot {0}" to Tr(ja = "スロット {0}を よみこみました", fr = "Emplacement {0} chargé", de = "Slot {0} geladen", it = "Slot {0} caricato", es = "Ranura {0} cargada", br = "Espaço {0} carregado", pt = "Espaço {0} carregado", ko = "슬롯 {0}을(를) 불러왔어요"),
    "Slot {0}: nothing to load" to Tr(ja = "スロット {0}: なにも ありません", fr = "Emplacement {0} : rien à charger", de = "Slot {0}: nichts zu laden", it = "Slot {0}: niente da caricare", es = "Ranura {0}: nada que cargar", br = "Espaço {0}: nada para carregar", pt = "Espaço {0}: nada para carregar", ko = "슬롯 {0}: 불러올 것이 없어요"),
    "Undid save (slot {0})" to Tr(ja = "ほぞんを とりけしました (スロット {0})", fr = "Enregistrement annulé ({0})", de = "Speichern rückgängig (Slot {0})", it = "Salvataggio annullato (slot {0})", es = "Guardado deshecho (ranura {0})", br = "Salvamento desfeito (espaço {0})", pt = "Gravação desfeita (espaço {0})", ko = "저장 취소함 (슬롯 {0})"),
    "Nothing to undo" to Tr(ja = "とりけす ものが ありません", fr = "Rien à annuler", de = "Nichts rückgängig zu machen", it = "Niente da annullare", es = "Nada que deshacer", br = "Nada para desfazer", pt = "Nada para desfazer", ko = "취소할 것이 없어요"),
    "Undid load" to Tr(ja = "よみこみを とりけしました", fr = "Chargement annulé", de = "Laden rückgängig", it = "Caricamento annullato", es = "Carga deshecha", br = "Carregamento desfeito", pt = "Carregamento desfeito", ko = "불러오기 취소함"),
    "Slot {0} (used)" to Tr(ja = "スロット {0} (しようちゅう)", fr = "Emplacement {0} (utilisé)", de = "Slot {0} (belegt)", it = "Slot {0} (usato)", es = "Ranura {0} (usada)", br = "Espaço {0} (usado)", pt = "Espaço {0} (usado)", ko = "슬롯 {0} (사용 중)"),
    "Slot {0} (empty)" to Tr(ja = "スロット {0} (から)", fr = "Emplacement {0} (vide)", de = "Slot {0} (leer)", it = "Slot {0} (vuoto)", es = "Ranura {0} (vacía)", br = "Espaço {0} (vazio)", pt = "Espaço {0} (vazio)", ko = "슬롯 {0} (비어 있음)"),
    // First-time setup
    "WELCOME TO POKéDAISY" to Tr(ja = "POKéDAISYへ ようこそ", fr = "BIENVENUE DANS POKéDAISY", de = "WILLKOMMEN BEI POKéDAISY", it = "BENVENUTO IN POKéDAISY", es = "BIENVENIDO A POKéDAISY", br = "BEM-VINDO AO POKéDAISY", pt = "BEM-VINDO AO POKéDAISY", ko = "PokéDaisy에 오신 걸 환영해요"),
    "SKIP" to Tr(ja = "スキップ", fr = "PASSER", de = "ÜBERSPRINGEN", it = "SALTA", es = "OMITIR", br = "PULAR", pt = "SALTAR", ko = "건너뛰기"),
    "DONE" to Tr(ja = "おわり", fr = "TERMINÉ", de = "FERTIG", it = "FINE", es = "LISTO", br = "PRONTO", pt = "CONCLUÍDO", ko = "완료"),
    "NEXT|continue" to Tr(ja = "つぎへ", fr = "SUIVANT", de = "WEITER", it = "AVANTI", es = "SIGUIENTE", br = "PRÓXIMO", pt = "SEGUINTE", ko = "다음"),
    "YOUR ROMS FOLDERS" to Tr(ja = "ROMフォルダ", fr = "VOS DOSSIERS DE ROM", de = "DEINE ROM-ORDNER", it = "LE TUE CARTELLE ROM", es = "TUS CARPETAS DE ROM", br = "SUAS PASTAS DE ROMS", pt = "AS SUAS PASTAS DE ROMS", ko = "ROM 폴더"),
    "Pick the folders you keep your games in. PokéDaisy adds every game from them that the second screen supports, plays them right where they are (nothing is copied), and looks for new ones each time you open the app." to Tr(ja = "ゲームを いれている フォルダを えらんでください。 PokéDaisyは サブがめんが たいおうする ゲームを すべて ついかし、 その ばしょの まま プレイして (コピーは しません)、 アプリを ひらく たびに あたらしい ゲームを さがします。", fr = "Choisissez les dossiers où vous rangez vos jeux. PokéDaisy ajoute chaque jeu pris en charge par le 2nd écran, le lance sur place (rien n'est copié) et cherche les nouveaux à chaque ouverture de l'appli.", de = "Wähle die Ordner mit deinen Spielen. PokéDaisy fügt jedes Spiel daraus hinzu, das der 2. Bildschirm unterstützt, spielt es direkt dort (nichts wird kopiert) und sucht bei jedem App-Start nach neuen.", it = "Scegli le cartelle dove tieni i tuoi giochi. PokéDaisy aggiunge ogni gioco supportato dal secondo schermo, lo avvia lì dov'è (nulla viene copiato) e cerca quelli nuovi ogni volta che apri l'app.", es = "Elige las carpetas donde guardas tus juegos. PokéDaisy añade cada juego compatible con la 2.ª pantalla, lo abre donde está (no se copia nada) y busca nuevos cada vez que abres la app.", br = "Escolha as pastas onde você guarda seus jogos. O PokéDaisy adiciona todos os jogos delas que a segunda tela suporta, roda cada um onde está (nada é copiado) e procura novos sempre que você abre o app.", pt = "Escolha as pastas onde guarda os seus jogos. O PokéDaisy adiciona todos os jogos delas que o segundo ecrã suporta, abre-os onde estão (nada é copiado) e procura novos sempre que abre a app.", ko = "게임을 넣어 둔 폴더를 고르세요. PokéDaisy가 두 번째 화면이 지원하는 게임을 모두 추가하고, 그 자리에서 플레이하며(복사하지 않아요), 앱을 열 때마다 새 게임을 찾아요."),
    "This is optional: skip it and add games one at a time with + in the library. You can add folders later with + or in SETTINGS > FOLDERS." to Tr(ja = "これは しなくても だいじょうぶ: スキップして ライブラリの + で ひとつずつ ついか できます。 フォルダは あとで + か せってい > フォルダ でも ついか できます。", fr = "C'est facultatif : passez et ajoutez les jeux un par un avec + dans la bibliothèque. Vous pourrez ajouter des dossiers plus tard avec + ou dans OPTIONS > DOSSIERS.", de = "Das ist optional: Überspring es und füge Spiele einzeln mit + in der Bibliothek hinzu. Ordner kannst du später mit + oder unter OPTIONEN > ORDNER hinzufügen.", it = "È facoltativo: saltalo e aggiungi i giochi uno alla volta con + nella libreria. Puoi aggiungere cartelle più tardi con + o in OPZIONI > CARTELLE.", es = "Es opcional: omítelo y añade juegos de uno en uno con + en la biblioteca. Puedes añadir carpetas más tarde con + o en AJUSTES > CARPETAS.", br = "É opcional: pule e adicione jogos um a um com + na biblioteca. Você pode adicionar pastas depois com + ou em CONFIGURAÇÕES > PASTAS.", pt = "É opcional: salte este passo e adicione jogos um a um com + na biblioteca. Pode adicionar pastas mais tarde com + ou em DEFINIÇÕES > PASTAS.", ko = "이 단계는 선택이에요. 건너뛰고 라이브러리에서 +로 게임을 하나씩 추가해도 돼요. 폴더는 나중에 +나 설정 > 폴더에서 추가할 수 있어요."),
    "Android asks you to allow All files access first, so PokéDaisy can open games and saves outside its own folder. Turn it on and come back here." to Tr(ja = "さきに Androidが 「すべての ファイルへの アクセス」の きょかを もとめます。 PokéDaisyが じぶんの フォルダの そとの ゲームや セーブを ひらく ためです。 オンにして ここへ もどってください。", fr = "Android vous demande d'abord d'autoriser l'accès à tous les fichiers, pour que PokéDaisy puisse ouvrir jeux et sauvegardes hors de son dossier. Activez-le et revenez ici.", de = "Android fragt zuerst nach dem Zugriff auf alle Dateien, damit PokéDaisy Spiele und Speicherstände außerhalb seines Ordners öffnen kann. Schalte ihn ein und komm hierher zurück.", it = "Android chiede prima di consentire l'accesso a tutti i file, così PokéDaisy può aprire giochi e salvataggi fuori dalla sua cartella. Attivalo e torna qui.", es = "Android te pide primero permitir el acceso a todos los archivos, para que PokéDaisy pueda abrir juegos y partidas fuera de su carpeta. Actívalo y vuelve aquí.", br = "O Android pede primeiro que você permita o acesso a todos os arquivos, para que o PokéDaisy possa abrir jogos e saves fora da própria pasta. Ative e volte aqui.", pt = "O Android pede primeiro que permita o acesso a todos os ficheiros, para que o PokéDaisy possa abrir jogos e gravações fora da sua pasta. Ative-o e volte aqui.", ko = "PokéDaisy가 자기 폴더 밖의 게임과 세이브를 열 수 있도록 Android가 먼저 모든 파일 접근 허용을 요청해요. 켜고 여기로 돌아오세요."),
    "LOOKING FOR GAMES… {0} / {1}" to Tr(ja = "ゲームを さがしちゅう… {0} / {1}", fr = "RECHERCHE DE JEUX… {0} / {1}", de = "SUCHE SPIELE… {0} / {1}", it = "CERCO GIOCHI… {0} / {1}", es = "BUSCANDO JUEGOS… {0} / {1}", br = "PROCURANDO JOGOS… {0} / {1}", pt = "A PROCURAR JOGOS… {0} / {1}", ko = "게임을 찾는 중… {0} / {1}"),
    "No supported games in there. Add another folder, or skip and add games with + later." to Tr(ja = "たいおうする ゲームが ありません。 べつの フォルダを ついかするか、 スキップして あとで + で ついかしてください。", fr = "Aucun jeu pris en charge ici. Ajoutez un autre dossier, ou passez et ajoutez des jeux avec + plus tard.", de = "Keine unterstützten Spiele darin. Füge einen anderen Ordner hinzu oder überspring es und füge später Spiele mit + hinzu.", it = "Nessun gioco supportato qui. Aggiungi un'altra cartella, o salta e aggiungi i giochi con + più tardi.", es = "No hay juegos compatibles ahí. Añade otra carpeta, u omite y añade juegos con + más tarde.", br = "Nenhum jogo compatível aí. Adicione outra pasta ou pule e adicione jogos com + depois.", pt = "Nenhum jogo compatível aí. Adicione outra pasta ou salte e adicione jogos com + mais tarde.", ko = "지원되는 게임이 없어요. 다른 폴더를 추가하거나, 건너뛰고 나중에 +로 게임을 추가하세요."),
    "FOUND 1 GAME" to Tr(ja = "ゲームを 1こ みつけた", fr = "1 JEU TROUVÉ", de = "1 SPIEL GEFUNDEN", it = "1 GIOCO TROVATO", es = "1 JUEGO ENCONTRADO", br = "1 JOGO ENCONTRADO", pt = "1 JOGO ENCONTRADO", ko = "게임 1개 찾음"),
    "FOUND {0} GAMES" to Tr(ja = "ゲームを {0}こ みつけた", fr = "{0} JEUX TROUVÉS", de = "{0} SPIELE GEFUNDEN", it = "{0} GIOCHI TROVATI", es = "{0} JUEGOS ENCONTRADOS", br = "{0} JOGOS ENCONTRADOS", pt = "{0} JOGOS ENCONTRADOS", ko = "게임 {0}개 찾음"),
    "GAME SAVES" to Tr(ja = "セーブデータ", fr = "SAUVEGARDES", de = "SPEICHERSTÄNDE", it = "SALVATAGGI", es = "PARTIDAS GUARDADAS", br = "SAVES DOS JOGOS", pt = "JOGOS GUARDADOS", ko = "게임 세이브"),
    "Where should your saves go? If you already play these games in another emulator, pick its save folder (RetroArch's, for one) and carry on with the same saves: a game finds its save by the ROM's file name (.sav or .srm)." to Tr(ja = "セーブを どこに おきますか? ほかの エミュレーターで あそんでいるなら、 その セーブフォルダ (たとえば RetroArchの)を えらべば おなじ セーブで つづけられます: ゲームは ROMの ファイルめい (.sav か .srm)で セーブを さがします。", fr = "Où mettre vos sauvegardes ? Si vous jouez déjà à ces jeux dans un autre émulateur, choisissez son dossier de sauvegardes (celui de RetroArch, par exemple) et continuez avec les mêmes : un jeu trouve sa sauvegarde par le nom de fichier de la ROM (.sav ou .srm).", de = "Wohin mit deinen Speicherständen? Spielst du diese Spiele schon in einem anderen Emulator, wähle seinen Speicherordner (z. B. den von RetroArch) und spiel mit denselben weiter: Ein Spiel findet seinen Speicherstand über den Dateinamen des ROMs (.sav oder .srm).", it = "Dove vanno i salvataggi? Se giochi già a questi giochi in un altro emulatore, scegli la sua cartella dei salvataggi (quella di RetroArch, per esempio) e continua con gli stessi: un gioco trova il suo salvataggio dal nome file della ROM (.sav o .srm).", es = "¿Dónde van tus partidas? Si ya juegas a estos juegos en otro emulador, elige su carpeta de partidas (la de RetroArch, por ejemplo) y sigue con las mismas: cada juego encuentra su partida por el nombre de archivo de la ROM (.sav o .srm).", br = "Onde ficam seus saves? Se você já joga esses jogos em outro emulador, escolha a pasta de saves dele (a do RetroArch, por exemplo) e continue com os mesmos saves: cada jogo acha o save pelo nome do arquivo da ROM (.sav ou .srm).", pt = "Onde ficam os jogos guardados? Se já joga estes jogos noutro emulador, escolha a pasta de gravações dele (a do RetroArch, por exemplo) e continue com as mesmas gravações: cada jogo encontra a sua gravação pelo nome do ficheiro da ROM (.sav ou .srm).", ko = "세이브를 어디에 둘까요? 이미 다른 에뮬레이터로 이 게임들을 하고 있다면 그 세이브 폴더(예: RetroArch의 폴더)를 골라 같은 세이브로 이어서 하세요. 게임은 ROM 파일 이름으로 세이브를 찾아요 (.sav 또는 .srm)."),
    "KEEP THEM IN POKéDAISY" to Tr(ja = "POKéDAISYに おく", fr = "LES GARDER DANS POKéDAISY", de = "IN POKéDAISY BEHALTEN", it = "TIENILI IN POKéDAISY", es = "GUARDAR EN POKéDAISY", br = "MANTER NO POKéDAISY", pt = "GUARDAR NO POKéDAISY", ko = "POKéDAISY에 두기"),
    "DEFAULT" to Tr(ja = "ひょうじゅん", fr = "PAR DÉFAUT", de = "STANDARD", it = "PREDEFINITO", es = "POR DEFECTO", br = "PADRÃO", pt = "PREDEFINIDO", ko = "기본"),
    "1 SAVE" to Tr(ja = "セーブ 1こ", fr = "1 SAUVEGARDE", de = "1 SPEICHERSTAND", it = "1 SALVATAGGIO", es = "1 PARTIDA", br = "1 SAVE", pt = "1 GRAVAÇÃO", ko = "세이브 1개"),
    "{0} SAVES" to Tr(ja = "セーブ {0}こ", fr = "{0} SAUVEGARDES", de = "{0} SPEICHERSTÄNDE", it = "{0} SALVATAGGI", es = "{0} PARTIDAS", br = "{0} SAVES", pt = "{0} GRAVAÇÕES", ko = "세이브 {0}개"),
    "CHOOSE ANOTHER FOLDER…" to Tr(ja = "べつの フォルダを えらぶ…", fr = "CHOISIR UN AUTRE DOSSIER…", de = "ANDEREN ORDNER WÄHLEN…", it = "SCEGLI UN'ALTRA CARTELLA…", es = "ELEGIR OTRA CARPETA…", br = "ESCOLHER OUTRA PASTA…", pt = "ESCOLHER OUTRA PASTA…", ko = "다른 폴더 선택…"),
    "Choosing a folder asks for All files access first, as games and saves are opened by path." to Tr(ja = "フォルダを えらぶ まえに 「すべての ファイルへの アクセス」を もとめます。 ゲームと セーブは パスで ひらく ためです。", fr = "Choisir un dossier demande d'abord l'accès à tous les fichiers, car jeux et sauvegardes sont ouverts par leur chemin.", de = "Die Ordnerwahl fragt zuerst nach dem Zugriff auf alle Dateien, da Spiele und Speicherstände über ihren Pfad geöffnet werden.", it = "Scegliere una cartella richiede prima l'accesso a tutti i file, perché giochi e salvataggi si aprono dal percorso.", es = "Elegir una carpeta pide primero el acceso a todos los archivos, ya que juegos y partidas se abren por su ruta.", br = "Escolher uma pasta pede primeiro o acesso a todos os arquivos, pois jogos e saves são abertos pelo caminho.", pt = "Escolher uma pasta pede primeiro o acesso a todos os ficheiros, pois jogos e gravações são abertos pelo caminho.", ko = "폴더를 고르기 전에 모든 파일 접근 권한을 먼저 요청해요. 게임과 세이브를 경로로 열기 때문이에요."),
    "You can change this later in SETTINGS > FOLDERS." to Tr(ja = "あとで せってい > フォルダ で かえられます。", fr = "Vous pourrez le changer plus tard dans OPTIONS > DOSSIERS.", de = "Das kannst du später unter OPTIONEN > ORDNER ändern.", it = "Puoi cambiarlo più tardi in OPZIONI > CARTELLE.", es = "Puedes cambiarlo más tarde en AJUSTES > CARPETAS.", br = "Você pode mudar isso depois em CONFIGURAÇÕES > PASTAS.", pt = "Pode mudar isto mais tarde em DEFINIÇÕES > PASTAS.", ko = "나중에 설정 > 폴더에서 바꿀 수 있어요."),
    "COVER ART (OPTIONAL)" to Tr(ja = "カバー (にんい)", fr = "JAQUETTES (FACULTATIF)", de = "COVER (OPTIONAL)", it = "COPERTINE (FACOLTATIVO)", es = "PORTADAS (OPCIONAL)", br = "CAPAS (OPCIONAL)", pt = "CAPAS (OPCIONAL)", ko = "커버 아트 (선택)"),
    "Library covers are box art from RetroAchievements, or icons from SteamGridDB for games it doesn't have. Each needs your own free key: open the site, copy the key and paste it below - one is enough." to Tr(ja = "ライブラリの カバーは RetroAchievementsの パッケージ、 なければ SteamGridDBの アイコンです。 どちらも じぶんの むりょうの キーが ひつようです: サイトを ひらいて キーを コピーし したに はりつけて ください — ひとつで じゅうぶんです。", fr = "Les jaquettes sont les boîtes de RetroAchievements, ou des icônes de SteamGridDB pour les jeux qu'il n'a pas. Chacun demande votre propre clé gratuite : ouvrez le site, copiez la clé et collez-la ci-dessous - une seule suffit.", de = "Bibliothek-Cover sind Verpackungen von RetroAchievements oder Icons von SteamGridDB für Spiele, die es nicht hat. Beide brauchen deinen eigenen kostenlosen Schlüssel: Öffne die Seite, kopiere den Schlüssel und füge ihn unten ein - einer reicht.", it = "Le copertine sono le confezioni di RetroAchievements, o icone di SteamGridDB per i giochi che non ha. Ognuno richiede la tua chiave gratuita: apri il sito, copia la chiave e incollala qui sotto - ne basta una.", es = "Las portadas son cajas de RetroAchievements, o iconos de SteamGridDB para los juegos que no tiene. Cada uno necesita tu propia clave gratis: abre el sitio, copia la clave y pégala abajo - con una basta.", br = "As capas da biblioteca são caixas do RetroAchievements, ou ícones do SteamGridDB para os jogos que ele não tem. Cada um precisa da sua própria chave grátis: abra o site, copie a chave e cole abaixo - uma basta.", pt = "As capas da biblioteca são caixas do RetroAchievements, ou ícones do SteamGridDB para os jogos que ele não tem. Cada um precisa da sua própria chave gratuita: abra o site, copie a chave e cole-a abaixo - uma basta.", ko = "라이브러리 커버는 RetroAchievements의 패키지 아트예요. 거기에 없는 게임은 SteamGridDB의 아이콘을 써요. 둘 다 무료 개인 키가 필요해요: 사이트를 열고 키를 복사해서 아래에 붙여 넣으세요. 하나면 충분해요."),
    "Skip this if you like - you can add a key any time in SETTINGS > COVER ART." to Tr(ja = "スキップしても だいじょうぶ - キーは いつでも せってい > カバー で いれられます。", fr = "Passez si vous voulez - vous pourrez ajouter une clé à tout moment dans OPTIONS > JAQUETTES.", de = "Überspring das ruhig - einen Schlüssel kannst du jederzeit unter OPTIONEN > COVER eingeben.", it = "Saltalo se vuoi - puoi aggiungere una chiave quando vuoi in OPZIONI > COPERTINE.", es = "Omítelo si quieres - puedes añadir una clave cuando quieras en AJUSTES > PORTADAS.", br = "Pule isto se quiser - você pode adicionar uma chave quando quiser em CONFIGURAÇÕES > CAPAS.", pt = "Salte isto se quiser - pode adicionar uma chave quando quiser em DEFINIÇÕES > CAPAS.", ko = "건너뛰어도 괜찮아요. 키는 언제든 설정 > 커버 아트에서 넣을 수 있어요."),
    "OPEN {0}" to Tr(ja = "{0}を ひらく", fr = "OUVRIR {0}", de = "{0} ÖFFNEN", it = "APRI {0}", es = "ABRIR {0}", br = "ABRIR {0}", pt = "ABRIR {0}", ko = "{0} 열기"),
    "GET KEY" to Tr(ja = "キーを とる", fr = "OBTENIR LA CLÉ", de = "SCHLÜSSEL HOLEN", it = "OTTIENI CHIAVE", es = "OBTENER CLAVE", br = "OBTER CHAVE", pt = "OBTER CHAVE", ko = "키 받기"),
    "SD CARD" to Tr(ja = "SDカード", fr = "CARTE SD", de = "SD-KARTE", it = "SCHEDA SD", es = "TARJETA SD", br = "CARTÃO SD", pt = "CARTÃO SD", ko = "SD 카드"),
    // In-game HUD (EmulatorEngine / PokeDaisyActivity).
    "Game restarted" to Tr(ja = "ゲームを リスタートしました", fr = "Jeu redémarré", de = "Spiel neu gestartet", it = "Gioco riavviato", es = "Juego reiniciado", br = "Jogo reiniciado", pt = "Jogo reiniciado", ko = "게임을 다시 시작했어요"),
    "Fast-forward" to Tr(ja = "はやおくり", fr = "Avance rapide", de = "Vorspulen", it = "Avanti veloce", es = "Avance rápido", br = "Avanço rápido", pt = "Avanço rápido", ko = "빨리 감기"),
    // BATTLE STYLE's one-time pick (BattleStyleIntro).
    "NEW: BATTLE STYLE" to Tr(ja = "NEW: バトルの みため", fr = "NOUVEAU : STYLE DE COMBAT", de = "NEU: KAMPFSTIL", it = "NOVITÀ: STILE LOTTA", es = "NUEVO: ESTILO DE COMBATE", br = "NOVO: ESTILO DE BATALHA", pt = "NOVO: ESTILO DE BATALHA", ko = "NEW: 배틀 스타일"),
    "Pick the look of the companion's battle screen. Both work the same way." to Tr(ja = "コンパニオンの バトルがめんの みためを えらんでください。 どちらも つかいかたは おなじです。", fr = "Choisissez l'apparence de l'écran de combat du compagnon. Les deux marchent de la même façon.", de = "Wähle das Aussehen des Kampfbildschirms des Begleiters. Beide funktionieren gleich.", it = "Scegli l'aspetto della schermata di lotta del compagno. Funzionano allo stesso modo.", es = "Elige el aspecto de la pantalla de combate del compañero. Las dos funcionan igual.", br = "Escolha a aparência da tela de batalha do companheiro. As duas funcionam do mesmo jeito.", pt = "Escolha o aspeto do ecrã de batalha do companheiro. Os dois funcionam da mesma forma.", ko = "컴패니언 배틀 화면의 모습을 골라 주세요. 둘 다 쓰는 법은 같아요."),
    "Change it any time in the companion's SETTINGS > BATTLE STYLE." to Tr(ja = "コンパニオンの せってい > バトルの みため で いつでも かえられます。", fr = "Modifiable à tout moment dans les OPTIONS du compagnon > STYLE DE COMBAT.", de = "Jederzeit änderbar in den OPTIONEN des Begleiters > KAMPFSTIL.", it = "Puoi cambiarlo quando vuoi nelle OPZIONI del compagno > STILE LOTTA.", es = "Cámbialo cuando quieras en los AJUSTES del compañero > ESTILO DE COMBATE.", br = "Mude quando quiser nas CONFIGURAÇÕES do companheiro > ESTILO DE BATALHA.", pt = "Altere quando quiser nas DEFINIÇÕES do companheiro > ESTILO DE BATALHA.", ko = "컴패니언의 설정 > 배틀 스타일에서 언제든 바꿀 수 있어요."),
    // EXPAND's one-time introduction (ExpandIntro).
    "WHAT'S NEW" to Tr(ja = "あたらしい こと", fr = "NOUVEAUTÉS", de = "NEUIGKEITEN", it = "NOVITÀ", es = "NOVEDADES", br = "NOVIDADES", pt = "NOVIDADES", ko = "새로운 기능"),
    "FIXES" to Tr(ja = "なおした こと", fr = "CORRECTIFS", de = "BEHOBEN", it = "CORREZIONI", es = "ARREGLOS", br = "CORREÇÕES", pt = "CORREÇÕES", ko = "수정 사항"),
    "NEW: EXPAND" to Tr(ja = "NEW: ひろげる", fr = "NOUVEAU : ÉTENDRE", de = "NEU: ERWEITERN", it = "NOVITÀ: ESPANDI", es = "NUEVO: AMPLIAR", br = "NOVO: EXPANDIR", pt = "NOVO: EXPANDIR", ko = "NEW: 확장"),
    "See more of the world around you. EXPAND draws the map past the game's edges, so the whole screen is the game: no black bars, nothing stretched." to Tr(ja = "まわりの せかいが もっと みえる。 ひろげるは ゲームの はしの さきまで マップを えがくので がめん ぜんぶが ゲームに なります。 くろい おびも ひきのばしも なし。", fr = "Voyez plus du monde autour de vous. ÉTENDRE dessine la carte au-delà des bords du jeu : tout l'écran est le jeu, sans bandes noires ni étirement.", de = "Sieh mehr von der Welt um dich herum. ERWEITERN zeichnet die Karte über die Ränder des Spiels hinaus: Der ganze Bildschirm ist das Spiel, ohne schwarze Balken, nichts verzerrt.", it = "Vedi di più del mondo intorno a te. ESPANDI disegna la mappa oltre i bordi del gioco: tutto lo schermo è il gioco, senza bande nere né stiramenti.", es = "Ve más del mundo a tu alrededor. AMPLIAR dibuja el mapa más allá de los bordes del juego: toda la pantalla es el juego, sin franjas negras ni nada estirado.", br = "Veja mais do mundo ao seu redor. EXPANDIR desenha o mapa além das bordas do jogo, então a tela inteira é o jogo: sem barras pretas, nada esticado.", pt = "Veja mais do mundo à sua volta. EXPANDIR desenha o mapa além das margens do jogo, por isso o ecrã inteiro é o jogo: sem barras pretas, nada esticado.", ko = "주변 세계를 더 넓게 볼 수 있어요. 확장은 게임 화면 가장자리 너머까지 맵을 그려서 화면 전체가 게임이 돼요. 검은 띠도, 늘어난 화면도 없어요."),
    "Press R3 to zoom out and see further, and look around with the right stick. Battles, menus and conversations zoom back in by themselves." to Tr(ja = "R3で ズームアウトして とおくまで みえる。 みぎスティックで みまわせます。 バトルや メニューや かいわでは じどうで もどります。", fr = "R3 pour dézoomer et voir plus loin, le stick droit pour regarder autour. Combats, menus et dialogues rezooment d'eux-mêmes.", de = "R3 zoomt heraus, damit du weiter siehst, mit dem rechten Stick schaust du dich um. Kämpfe, Menüs und Gespräche zoomen von selbst wieder heran.", it = "Premi R3 per allontanare la vista e vedere più lontano, guardati intorno con lo stick destro. Lotte, menu e dialoghi tornano vicini da soli.", es = "Pulsa R3 para alejar la vista y ver más lejos, y mira alrededor con el stick derecho. Combates, menús y conversaciones vuelven a acercarse solos.", br = "Aperte R3 para afastar a câmera e ver mais longe, e olhe em volta com o analógico direito. Batalhas, menus e conversas voltam a aproximar sozinhos.", pt = "Carregue em R3 para afastar a câmara e ver mais longe, e olhe em volta com o analógico direito. Batalhas, menus e conversas voltam a aproximar sozinhos.", ko = "R3을 누르면 줌아웃해서 더 멀리 볼 수 있고, 오른쪽 스틱으로 둘러볼 수 있어요. 배틀, 메뉴, 대화에서는 저절로 다시 줌인돼요."),
    "Works in selected games, with more added all the time. Change it any time in SETTINGS > ASPECT." to Tr(ja = "いくつかの ゲームで つかえます。 たいおうゲームは どんどん ふえます。 せってい > アスペクトで いつでも かえられます。", fr = "Fonctionne dans certains jeux, et d'autres arrivent sans cesse. À changer quand vous voulez dans OPTIONS > FORMAT.", de = "Funktioniert in ausgewählten Spielen, und es kommen ständig neue dazu. Jederzeit änderbar unter OPTIONEN > FORMAT.", it = "Funziona in alcuni giochi, e se ne aggiungono sempre di nuovi. Puoi cambiarlo quando vuoi in OPZIONI > FORMATO.", es = "Funciona en algunos juegos, y añadimos más todo el tiempo. Cámbialo cuando quieras en AJUSTES > FORMATO.", br = "Funciona em alguns jogos, e sempre adicionamos mais. Mude quando quiser em CONFIGURAÇÕES > PROPORÇÃO.", pt = "Funciona em alguns jogos, e estamos sempre a adicionar mais. Mude quando quiser em DEFINIÇÕES > PROPORÇÃO.", ko = "일부 게임에서 쓸 수 있고, 지원 게임은 계속 늘어나요. 설정 > 화면 비율에서 언제든 바꿀 수 있어요."),
    "Change it any time in SETTINGS > ASPECT." to Tr(ja = "せってい > アスペクトで いつでも かえられます。", fr = "À changer quand vous voulez dans OPTIONS > FORMAT.", de = "Jederzeit änderbar unter OPTIONEN > FORMAT.", it = "Puoi cambiarlo quando vuoi in OPZIONI > FORMATO.", es = "Cámbialo cuando quieras en AJUSTES > FORMATO.", br = "Mude quando quiser em CONFIGURAÇÕES > PROPORÇÃO.", pt = "Mude quando quiser em DEFINIÇÕES > PROPORÇÃO.", ko = "설정 > 화면 비율에서 언제든 바꿀 수 있어요."),
    "EXPAND WORKS IN THIS GAME" to Tr(ja = "この ゲームは ひろげるに たいおう", fr = "ÉTENDRE MARCHE DANS CE JEU", de = "ERWEITERN GEHT IN DIESEM SPIEL", it = "ESPANDI FUNZIONA IN QUESTO GIOCO", es = "AMPLIAR FUNCIONA EN ESTE JUEGO", br = "EXPANDIR FUNCIONA NESTE JOGO", pt = "EXPANDIR FUNCIONA NESTE JOGO", ko = "이 게임은 확장 지원"),
    "NOT NOW" to Tr(ja = "あとで", fr = "PLUS TARD", de = "SPÄTER", it = "NON ORA", es = "AHORA NO", br = "AGORA NÃO", pt = "AGORA NÃO", ko = "나중에"),
    "TURN ON" to Tr(ja = "オンにする", fr = "ACTIVER", de = "EINSCHALTEN", it = "ATTIVA", es = "ACTIVAR", br = "ATIVAR", pt = "ATIVAR", ko = "켜기"),
    "EXPAND hit a problem and is off for this game" to Tr(ja = "ひろげるで もんだいが おきたので この ゲームでは オフに しました", fr = "ÉTENDRE a eu un problème : désactivé pour ce jeu", de = "ERWEITERN hatte ein Problem und ist für dieses Spiel aus", it = "ESPANDI ha avuto un problema: disattivato per questo gioco", es = "AMPLIAR tuvo un problema y se desactivó para este juego", br = "EXPANDIR teve um problema e foi desativado neste jogo", pt = "EXPANDIR teve um problema e foi desativado neste jogo", ko = "확장에 문제가 생겨서 이 게임에서는 꺼졌어요"),
    "Zoom {0}" to Tr(ja = "ズーム {0}", fr = "Zoom {0}", de = "Zoom {0}", it = "Zoom {0}", es = "Zoom {0}", br = "Zoom {0}", pt = "Zoom {0}", ko = "줌 {0}"),
    "Zoom needs ASPECT > EXPAND" to Tr(ja = "ズームは アスペクト > ひろげる で", fr = "Le zoom demande FORMAT > ÉTENDRE", de = "Zoom braucht FORMAT > ERWEITERN", it = "Lo zoom richiede FORMATO > ESPANDI", es = "El zoom necesita FORMATO > AMPLIAR", br = "O zoom precisa de PROPORÇÃO > EXPANDIR", pt = "O zoom precisa de PROPORÇÃO > EXPANDIR", ko = "줌은 화면 비율 > 확장이 필요해요"),
    "Game muted" to Tr(ja = "ゲームを ミュートしました", fr = "Jeu muet", de = "Spiel stumm", it = "Gioco muto", es = "Juego silenciado", br = "Jogo silenciado", pt = "Jogo silenciado", ko = "게임 음소거"),
    "Game sound on" to Tr(ja = "ゲームの おとを オン", fr = "Son du jeu activé", de = "Spielton an", it = "Audio del gioco attivo", es = "Sonido del juego activado", br = "Som do jogo ligado", pt = "Som do jogo ligado", ko = "게임 소리 켜짐"),
    "Soft reset" to Tr(ja = "ソフトリセット", fr = "Réinitialisation douce", de = "Soft-Reset", it = "Reset soft", es = "Reinicio suave", br = "Reinício suave", pt = "Reinício suave", ko = "소프트 리셋"),
    "Rewinding" to Tr(ja = "まきもどし ちゅう", fr = "Retour arrière", de = "Zurückspulen", it = "Riavvolgimento", es = "Rebobinando", br = "Rebobinando", pt = "A rebobinar", ko = "되감는 중"),
    "Rewind doesn't work in DS games" to Tr(ja = "DSの ゲームでは まきもどし できません", fr = "Le retour arrière ne marche pas sur DS", de = "Zurückspulen geht nicht bei DS-Spielen", it = "Il riavvolgimento non funziona sui giochi DS", es = "Rebobinar no funciona en juegos de DS", br = "Voltar no tempo não funciona em jogos de DS", pt = "Voltar atrás não funciona em jogos de DS", ko = "DS 게임에서는 되감기를 쓸 수 없어요"),
    "Rewind is off - turn it on in SETTINGS" to Tr(ja = "まきもどしは オフです - せっていで オンに", fr = "Retour arrière désactivé - activez-le dans OPTIONS", de = "Zurückspulen ist aus - in OPTIONEN einschalten", it = "Riavvolgimento disattivato - attivalo in OPZIONI", es = "Rebobinar está desactivado - actívalo en AJUSTES", br = "Rebobinar está desativado - ative em CONFIG.", pt = "Rebobinar está desativado - ative-o em DEFINIÇÕES", ko = "되감기가 꺼져 있어요. 설정에서 켜세요"),
    "Slow-motion ½×" to Tr(ja = "スロー ½×", fr = "Ralenti ½×", de = "Zeitlupe ½×", it = "Rallentatore ½×", es = "Cámara lenta ½×", br = "Câmera lenta ½×", pt = "Câmara lenta ½×", ko = "슬로 모션 ½×"),
    "Normal speed" to Tr(ja = "ふつうの はやさ", fr = "Vitesse normale", de = "Normale Geschwindigkeit", it = "Velocità normale", es = "Velocidad normal", br = "Velocidade normal", pt = "Velocidade normal", ko = "보통 속도"),
    "Speed {0}×" to Tr(ja = "はやさ {0}×", fr = "Vitesse {0}×", de = "Tempo {0}×", it = "Velocità {0}×", es = "Velocidad {0}×", br = "Velocidade {0}×", pt = "Velocidade {0}×", ko = "속도 {0}×"),
    "This save was compressed by RetroArch in a way PokeDaisy can't read yet, so it was left as it is. In RetroArch, turn off Settings > Saving > SaveRAM Compression, then load the game there and save once." to Tr(ja = "この セーブは RetroArchで あっしゅく されていて まだ よめないので そのままに しました。 RetroArchの せってい > セーブ > SaveRAMの あっしゅくを オフにして そちらで ゲームを ひらき いちど セーブしてください", fr = "Cette sauvegarde a été compressée par RetroArch d'une façon que PokeDaisy ne sait pas encore lire, elle n'a donc pas été touchée. Dans RetroArch, désactive Réglages > Sauvegarde > Compression de la SaveRAM, puis lance le jeu là et sauvegarde une fois.", de = "Dieser Spielstand wurde von RetroArch so komprimiert, dass PokeDaisy ihn noch nicht lesen kann, daher blieb er unverändert. Schalte in RetroArch Einstellungen > Speichern > SaveRAM-Komprimierung aus, lade das Spiel dort und speichere einmal.", it = "Questo salvataggio è stato compresso da RetroArch in un modo che PokeDaisy non sa ancora leggere, quindi è rimasto com'era. In RetroArch disattiva Impostazioni > Salvataggio > Compressione SaveRAM, poi apri il gioco lì e salva una volta.", es = "RetroArch comprimió esta partida de una forma que PokeDaisy aún no sabe leer, así que se dejó como estaba. En RetroArch, desactiva Ajustes > Guardado > Compresión de SaveRAM, abre el juego allí y guarda una vez.", br = "Este save foi comprimido pelo RetroArch de um jeito que o PokeDaisy ainda não lê, então ele foi deixado como estava. No RetroArch, desligue Configurações > Salvamento > Compressão da SaveRAM, abra o jogo lá e salve uma vez.", pt = "Esta gravação foi comprimida pelo RetroArch de uma forma que o PokeDaisy ainda não lê, por isso ficou como estava. No RetroArch, desliga Definições > Gravação > Compressão da SaveRAM, abre o jogo lá e grava uma vez.", ko = "이 세이브는 RetroArch가 PokeDaisy에서 아직 읽을 수 없는 방식으로 압축해서 그대로 두었어요. RetroArch에서 Settings > Saving > SaveRAM Compression을 끄고, 거기서 게임을 불러와 한 번 저장하세요."),
    "Couldn't back up {0}, so it was left as it is" to Tr(ja = "{0}の バックアップが とれなかったので そのままに しました", fr = "Impossible de sauvegarder une copie de {0}, il n'a donc pas été touché", de = "{0} konnte nicht gesichert werden, daher blieb es unverändert", it = "Impossibile fare una copia di {0}, quindi è rimasto com'era", es = "No se pudo hacer una copia de {0}, así que se dejó como estaba", br = "Não deu para fazer backup de {0}, então ele foi deixado como estava", pt = "Não foi possível fazer cópia de {0}, por isso ficou como estava", ko = "{0} 백업을 만들 수 없어서 그대로 두었어요"),
    "Your save changed since you last played here, so the game started from the save file" to Tr(ja = "まえに ここで あそんだあと セーブが かわったので セーブファイルから はじめました", fr = "Ta sauvegarde a changé depuis ta dernière partie ici : le jeu a démarré depuis le fichier de sauvegarde", de = "Dein Spielstand hat sich seit dem letzten Spiel hier geändert, daher startete das Spiel aus der Speicherdatei", it = "Il salvataggio è cambiato dall'ultima partita qui, quindi il gioco è partito dal file di salvataggio", es = "Tu partida cambió desde la última vez que jugaste aquí, así que el juego empezó desde el archivo de guardado", br = "Seu save mudou desde a última vez que você jogou aqui, então o jogo começou pelo arquivo de save", pt = "A gravação mudou desde a última vez que jogou aqui, por isso o jogo começou pelo ficheiro de gravação", ko = "마지막으로 여기서 플레이한 뒤 세이브가 바뀌어서 세이브 파일에서 게임을 시작했어요"),
    "This game was left on the other DS core, so it started from the save file" to Tr(ja = "このゲームは べつの DS エミュレータで とちゅうだったので セーブファイルから はじめました", fr = "Ce jeu a été laissé sur l'autre cœur DS : il a démarré depuis le fichier de sauvegarde", de = "Dieses Spiel wurde im anderen DS-Kern verlassen, daher startete es aus der Speicherdatei", it = "Questo gioco è stato lasciato sull'altro core DS, quindi è partito dal file di salvataggio", es = "Este juego se dejó en el otro núcleo DS, así que empezó desde el archivo de guardado", br = "Este jogo ficou no outro núcleo DS, então começou pelo arquivo de save", pt = "Este jogo ficou no outro núcleo DS, por isso começou pelo ficheiro de gravação", ko = "이 게임은 다른 DS 코어에서 멈춘 상태라 세이브 파일에서 시작했어요"),
    // ScreenScraper: sign-in, the update's popup, setup's GAME MEDIA step, Settings > ScreenScraper
    "ScreenScraper stopped: {0}" to Tr(ja = "ScreenScraperが とまりました: {0}", fr = "ScreenScraper arrêté : {0}", de = "ScreenScraper gestoppt: {0}", it = "ScreenScraper fermato: {0}", es = "ScreenScraper se detuvo: {0}", br = "O ScreenScraper parou: {0}", pt = "O ScreenScraper parou: {0}", ko = "ScreenScraper 중단됨: {0}"),
    "No account in the answer" to Tr(ja = "こたえに アカウントが ありません", fr = "Aucun compte dans la réponse", de = "Kein Konto in der Antwort", it = "Nessun account nella risposta", es = "No hay cuenta en la respuesta", br = "Nenhuma conta na resposta", pt = "Nenhuma conta na resposta", ko = "응답에 계정 정보가 없어요"),
    "This build has no ScreenScraper developer access" to Tr(ja = "この ビルドは ScreenScraperの かいはつしゃ アクセスが ありません", fr = "Cette version n'a pas d'accès développeur ScreenScraper", de = "Diese Version hat keinen ScreenScraper-Entwicklerzugang", it = "Questa versione non ha l'accesso sviluppatore ScreenScraper", es = "Esta versión no tiene acceso de desarrollador a ScreenScraper", br = "Esta versão não tem acesso de desenvolvedor ao ScreenScraper", pt = "Esta versão não tem acesso de programador ao ScreenScraper", ko = "이 빌드에는 ScreenScraper 개발자 권한이 없어요"),
    "Wrong username or password" to Tr(ja = "ユーザーめいか パスワードが ちがいます", fr = "Identifiant ou mot de passe incorrect", de = "Benutzername oder Passwort falsch", it = "Nome utente o password errati", es = "Usuario o contraseña incorrectos", br = "Usuário ou senha incorretos", pt = "Utilizador ou palavra-passe incorretos", ko = "사용자 이름 또는 비밀번호가 틀렸어요"),
    "Game not found" to Tr(ja = "ゲームが みつかりません", fr = "Jeu introuvable", de = "Spiel nicht gefunden", it = "Gioco non trovato", es = "Juego no encontrado", br = "Jogo não encontrado", pt = "Jogo não encontrado", ko = "게임을 찾을 수 없어요"),
    "ScreenScraper's API is closed for now" to Tr(ja = "ScreenScraperの APIは いま とじています", fr = "L'API de ScreenScraper est fermée pour l'instant", de = "Die ScreenScraper-API ist gerade geschlossen", it = "L'API di ScreenScraper è chiusa per ora", es = "La API de ScreenScraper está cerrada por ahora", br = "A API do ScreenScraper está fechada por enquanto", pt = "A API do ScreenScraper está fechada por agora", ko = "ScreenScraper API가 지금은 닫혀 있어요"),
    "ScreenScraper doesn't accept this app version" to Tr(ja = "ScreenScraperが この バージョンを うけつけません", fr = "ScreenScraper refuse cette version de l'app", de = "ScreenScraper akzeptiert diese App-Version nicht", it = "ScreenScraper non accetta questa versione dell'app", es = "ScreenScraper no acepta esta versión de la app", br = "O ScreenScraper não aceita esta versão do app", pt = "O ScreenScraper não aceita esta versão da app", ko = "ScreenScraper가 이 앱 버전을 받지 않아요"),
    "Too many requests at once" to Tr(ja = "いちどに リクエストが おおすぎます", fr = "Trop de requêtes à la fois", de = "Zu viele Anfragen auf einmal", it = "Troppe richieste insieme", es = "Demasiadas solicitudes a la vez", br = "Muitas solicitações ao mesmo tempo", pt = "Demasiados pedidos ao mesmo tempo", ko = "한 번에 요청이 너무 많아요"),
    "Today's ScreenScraper quota is used up" to Tr(ja = "きょうの ScreenScraperの りょうを つかいきりました", fr = "Le quota ScreenScraper du jour est épuisé", de = "Das heutige ScreenScraper-Kontingent ist aufgebraucht", it = "La quota ScreenScraper di oggi è esaurita", es = "Se agotó la cuota de ScreenScraper de hoy", br = "A cota de hoje do ScreenScraper acabou", pt = "A quota de hoje do ScreenScraper esgotou-se", ko = "오늘의 ScreenScraper 사용량을 다 썼어요"),
    "Too many unknown ROMs today" to Tr(ja = "きょうは しらない ROMが おおすぎます", fr = "Trop de ROM inconnues aujourd'hui", de = "Heute zu viele unbekannte ROMs", it = "Troppe ROM sconosciute oggi", es = "Demasiadas ROM desconocidas hoy", br = "Muitas ROMs desconhecidas hoje", pt = "Demasiadas ROMs desconhecidas hoje", ko = "오늘은 알 수 없는 ROM이 너무 많아요"),
    "Can't reach ScreenScraper - check the connection" to Tr(ja = "ScreenScraperに つながりません - せつぞくを たしかめてください", fr = "Impossible de joindre ScreenScraper - vérifiez la connexion", de = "ScreenScraper nicht erreichbar - prüf die Verbindung", it = "Impossibile raggiungere ScreenScraper - controlla la connessione", es = "No se puede conectar con ScreenScraper - revisa la conexión", br = "Não foi possível acessar o ScreenScraper - verifique a conexão", pt = "Não foi possível aceder ao ScreenScraper - verifique a ligação", ko = "ScreenScraper에 연결할 수 없어요. 인터넷 연결을 확인하세요"),
    "{0} OF {1} REQUESTS USED TODAY" to Tr(ja = "きょう {1}かいのうち {0}かい つかいました", fr = "{0} SUR {1} REQUÊTES UTILISÉES AUJOURD'HUI", de = "{0} VON {1} ANFRAGEN HEUTE GENUTZT", it = "{0} DI {1} RICHIESTE USATE OGGI", es = "{0} DE {1} SOLICITUDES USADAS HOY", br = "{0} DE {1} SOLICITAÇÕES USADAS HOJE", pt = "{0} DE {1} PEDIDOS USADOS HOJE", ko = "오늘 요청 {1}회 중 {0}회 사용"),
    "screenscraper.fr username" to Tr(ja = "screenscraper.frの ユーザーめい", fr = "identifiant screenscraper.fr", de = "screenscraper.fr-Benutzername", it = "nome utente screenscraper.fr", es = "usuario de screenscraper.fr", br = "usuário do screenscraper.fr", pt = "utilizador do screenscraper.fr", ko = "screenscraper.fr 사용자 이름"),
    "NO ACCOUNT? SIGN UP" to Tr(ja = "アカウントを つくる", fr = "PAS DE COMPTE ? S'INSCRIRE", de = "KEIN KONTO? REGISTRIEREN", it = "NESSUN ACCOUNT? REGISTRATI", es = "¿SIN CUENTA? REGÍSTRATE", br = "SEM CONTA? CADASTRE-SE", pt = "SEM CONTA? REGISTE-SE", ko = "계정이 없나요? 가입하기"),
    "NEW: GAME MEDIA FROM SCREENSCRAPER" to Tr(ja = "あたらしい: ScreenScraperの ゲームメディア", fr = "NOUVEAU : MÉDIAS DE JEU SCREENSCRAPER", de = "NEU: SPIELMEDIEN VON SCREENSCRAPER", it = "NOVITÀ: MEDIA DI GIOCO DA SCREENSCRAPER", es = "NUEVO: MEDIOS DE JUEGO DE SCREENSCRAPER", br = "NOVO: MÍDIA DE JOGOS DO SCREENSCRAPER", pt = "NOVO: MULTIMÉDIA DE JOGOS DO SCREENSCRAPER", ko = "NEW: ScreenScraper 게임 미디어"),
    "Box art, screenshots, title screens, logos, videos and each game's story for your whole library, from ScreenScraper.fr. It comes first for covers, and with two screens the library shows the game you're on, in full, on the other one." to Tr(ja = "ScreenScraper.frから ライブラリ ぜんぶの パッケージ、 スクリーンショット、 タイトルがめん、 ロゴ、 どうが、 ゲームの あらすじを とってきます。 カバーには これが いちばんに つかわれ、 がめんが ふたつ あれば えらんだ ゲームの すべてを もう ひとつの がめんに だします。", fr = "Jaquettes, captures, écrans titre, logos, vidéos et le résumé de chaque jeu pour toute votre bibliothèque, depuis ScreenScraper.fr. Il passe en premier pour les jaquettes et, avec deux écrans, la bibliothèque affiche le jeu sélectionné en entier sur l'autre.", de = "Cover, Screenshots, Titelbildschirme, Logos, Videos und die Story jedes Spiels für deine ganze Bibliothek, von ScreenScraper.fr. Es kommt bei Covern zuerst, und mit zwei Bildschirmen zeigt die Bibliothek das gewählte Spiel ganz auf dem anderen.", it = "Copertine, screenshot, schermate del titolo, loghi, video e la trama di ogni gioco per tutta la libreria, da ScreenScraper.fr. Ha la precedenza per le copertine e, con due schermi, la libreria mostra il gioco selezionato per intero sull'altro.", es = "Portadas, capturas, pantallas de título, logotipos, vídeos y la historia de cada juego para toda tu biblioteca, de ScreenScraper.fr. Tiene prioridad para las portadas y, con dos pantallas, la biblioteca muestra el juego elegido entero en la otra.", br = "Capas, capturas de tela, telas de título, logotipos, vídeos e a história de cada jogo para toda a sua biblioteca, do ScreenScraper.fr. Tem prioridade nas capas e, com duas telas, a biblioteca mostra o jogo selecionado, completo, na outra.", pt = "Capas, capturas de ecrã, ecrãs de título, logótipos, vídeos e a história de cada jogo para toda a sua biblioteca, do ScreenScraper.fr. Tem prioridade nas capas e, com dois ecrãs, a biblioteca mostra o jogo selecionado, completo, no outro.", ko = "ScreenScraper.fr에서 라이브러리 전체의 패키지 아트, 스크린샷, 타이틀 화면, 로고, 동영상, 게임 줄거리를 가져와요. 커버는 이것을 가장 먼저 쓰고, 화면이 두 개라면 고른 게임의 모든 정보를 다른 화면에 보여 줘요."),
    "It needs a free screenscraper.fr account. Set it up now?" to Tr(ja = "むりょうの screenscraper.frの アカウントが いります。 いま せっていしますか?", fr = "Il faut un compte screenscraper.fr gratuit. Le configurer maintenant ?", de = "Dafür brauchst du ein kostenloses screenscraper.fr-Konto. Jetzt einrichten?", it = "Serve un account gratuito screenscraper.fr. Configurarlo ora?", es = "Necesita una cuenta gratuita de screenscraper.fr. ¿Configurarla ahora?", br = "Precisa de uma conta gratuita do screenscraper.fr. Configurar agora?", pt = "Precisa de uma conta gratuita do screenscraper.fr. Configurar agora?", ko = "무료 screenscraper.fr 계정이 필요해요. 지금 설정할까요?"),
    "SIGNED IN AS {0}" to Tr(ja = "{0}で ログインちゅう", fr = "CONNECTÉ EN TANT QUE {0}", de = "ANGEMELDET ALS {0}", it = "ACCESSO COME {0}", es = "SESIÓN INICIADA COMO {0}", br = "CONECTADO COMO {0}", pt = "SESSÃO INICIADA COMO {0}", ko = "로그인됨: {0}"),
    "GAME MEDIA (OPTIONAL)" to Tr(ja = "ゲームメディア (にんい)", fr = "MÉDIAS DE JEU (FACULTATIF)", de = "SPIELMEDIEN (OPTIONAL)", it = "MEDIA DI GIOCO (FACOLTATIVO)", es = "MEDIOS DE JUEGO (OPCIONAL)", br = "MÍDIA DE JOGOS (OPCIONAL)", pt = "MULTIMÉDIA DE JOGOS (OPCIONAL)", ko = "게임 미디어 (선택)"),
    "ScreenScraper.fr has box art, screenshots, title screens, logos, videos and each game's story. Sign in with your free account and PokéDaisy fetches them for every game: covers in the library, and with two screens, everything about the game you're on on the other screen." to Tr(ja = "ScreenScraper.frには パッケージ、 スクリーンショット、 タイトルがめん、 ロゴ、 どうが、 ゲームの あらすじが あります。 むりょうの アカウントで ログインすると PokéDaisyが すべての ゲームの ぶんを とってきます: ライブラリの カバーと、 がめんが ふたつ あれば えらんだ ゲームの すべてを もう ひとつの がめんに。", fr = "ScreenScraper.fr a les jaquettes, captures, écrans titre, logos, vidéos et le résumé de chaque jeu. Connectez-vous avec votre compte gratuit et PokéDaisy les récupère pour chaque jeu : jaquettes dans la bibliothèque et, avec deux écrans, tout sur le jeu sélectionné sur l'autre écran.", de = "ScreenScraper.fr hat Cover, Screenshots, Titelbildschirme, Logos, Videos und die Story jedes Spiels. Melde dich mit deinem kostenlosen Konto an und PokéDaisy holt sie für jedes Spiel: Cover in der Bibliothek und, mit zwei Bildschirmen, alles über das gewählte Spiel auf dem anderen.", it = "ScreenScraper.fr ha copertine, screenshot, schermate del titolo, loghi, video e la trama di ogni gioco. Accedi con il tuo account gratuito e PokéDaisy li scarica per ogni gioco: copertine nella libreria e, con due schermi, tutto sul gioco selezionato sull'altro schermo.", es = "ScreenScraper.fr tiene portadas, capturas, pantallas de título, logotipos, vídeos y la historia de cada juego. Inicia sesión con tu cuenta gratuita y PokéDaisy los descarga para cada juego: portadas en la biblioteca y, con dos pantallas, todo sobre el juego elegido en la otra.", br = "O ScreenScraper.fr tem capas, capturas de tela, telas de título, logotipos, vídeos e a história de cada jogo. Entre com sua conta gratuita e o PokéDaisy baixa tudo para cada jogo: capas na biblioteca e, com duas telas, tudo sobre o jogo selecionado na outra tela.", pt = "O ScreenScraper.fr tem capas, capturas de ecrã, ecrãs de título, logótipos, vídeos e a história de cada jogo. Inicie sessão com a sua conta gratuita e o PokéDaisy transfere tudo para cada jogo: capas na biblioteca e, com dois ecrãs, tudo sobre o jogo selecionado no outro ecrã.", ko = "ScreenScraper.fr에는 패키지 아트, 스크린샷, 타이틀 화면, 로고, 동영상, 게임 줄거리가 있어요. 무료 계정으로 로그인하면 PokéDaisy가 모든 게임의 미디어를 가져와요: 라이브러리의 커버, 그리고 화면이 두 개라면 고른 게임의 모든 정보를 다른 화면에 보여 줘요."),
    "Skip this if you like - sign in any time in SETTINGS > SCREENSCRAPER." to Tr(ja = "スキップしても だいじょうぶ - いつでも せってい > SCREENSCRAPER で ログインできます。", fr = "Passez si vous voulez - connectez-vous quand vous voulez dans OPTIONS > SCREENSCRAPER.", de = "Überspring das ruhig - anmelden geht jederzeit unter OPTIONEN > SCREENSCRAPER.", it = "Puoi saltarlo - accedi quando vuoi in OPZIONI > SCREENSCRAPER.", es = "Puedes omitirlo - inicia sesión cuando quieras en AJUSTES > SCREENSCRAPER.", br = "Pule isto se quiser - entre quando quiser em CONFIGURAÇÕES > SCREENSCRAPER.", pt = "Salte isto se quiser - inicie sessão quando quiser em DEFINIÇÕES > SCREENSCRAPER.", ko = "건너뛰어도 괜찮아요. 설정 > ScreenScraper에서 언제든 로그인할 수 있어요."),
    "ScreenScraper.fr has box art, screenshots, title screens, logos, videos and each game's story. With your free account, PokéDaisy fetches them once per game and keeps them on the device. Its box art comes first for library covers, and with two screens the launcher shows the game you're on, in full, on the other one." to Tr(ja = "ScreenScraper.frには パッケージ、 スクリーンショット、 タイトルがめん、 ロゴ、 どうが、 ゲームの あらすじが あります。 むりょうの アカウントで PokéDaisyが ゲームごとに いちど とってきて きかいに のこします。 ライブラリの カバーには その パッケージが いちばんに つかわれ、 がめんが ふたつ あれば ランチャーが えらんだ ゲームの すべてを もう ひとつの がめんに だします。", fr = "ScreenScraper.fr a les jaquettes, captures, écrans titre, logos, vidéos et le résumé de chaque jeu. Avec votre compte gratuit, PokéDaisy les récupère une fois par jeu et les garde sur l'appareil. Ses jaquettes passent en premier dans la bibliothèque et, avec deux écrans, le lanceur affiche le jeu sélectionné en entier sur l'autre.", de = "ScreenScraper.fr hat Cover, Screenshots, Titelbildschirme, Logos, Videos und die Story jedes Spiels. Mit deinem kostenlosen Konto holt PokéDaisy sie einmal pro Spiel und behält sie auf dem Gerät. Seine Cover kommen in der Bibliothek zuerst, und mit zwei Bildschirmen zeigt der Launcher das gewählte Spiel ganz auf dem anderen.", it = "ScreenScraper.fr ha copertine, screenshot, schermate del titolo, loghi, video e la trama di ogni gioco. Con il tuo account gratuito, PokéDaisy li scarica una volta per gioco e li tiene sul dispositivo. Le sue copertine hanno la precedenza nella libreria e, con due schermi, il launcher mostra il gioco selezionato per intero sull'altro.", es = "ScreenScraper.fr tiene portadas, capturas, pantallas de título, logotipos, vídeos y la historia de cada juego. Con tu cuenta gratuita, PokéDaisy los descarga una vez por juego y los guarda en el dispositivo. Sus portadas tienen prioridad en la biblioteca y, con dos pantallas, el lanzador muestra el juego elegido entero en la otra.", br = "O ScreenScraper.fr tem capas, capturas de tela, telas de título, logotipos, vídeos e a história de cada jogo. Com sua conta gratuita, o PokéDaisy baixa tudo uma vez por jogo e guarda no aparelho. As capas dele têm prioridade na biblioteca e, com duas telas, o launcher mostra o jogo selecionado, completo, na outra.", pt = "O ScreenScraper.fr tem capas, capturas de ecrã, ecrãs de título, logótipos, vídeos e a história de cada jogo. Com a sua conta gratuita, o PokéDaisy transfere tudo uma vez por jogo e guarda-o no dispositivo. As capas dele têm prioridade na biblioteca e, com dois ecrãs, o launcher mostra o jogo selecionado, completo, no outro.", ko = "ScreenScraper.fr에는 패키지 아트, 스크린샷, 타이틀 화면, 로고, 동영상, 게임 줄거리가 있어요. 무료 계정이 있으면 PokéDaisy가 게임마다 한 번 가져와서 기기에 보관해요. 라이브러리 커버는 이 패키지 아트를 가장 먼저 쓰고, 화면이 두 개라면 런처가 고른 게임의 모든 정보를 다른 화면에 보여 줘요."),
    "DOWNLOAD VIDEOS" to Tr(ja = "どうがも ダウンロード", fr = "TÉLÉCHARGER LES VIDÉOS", de = "VIDEOS LADEN", it = "SCARICA VIDEO", es = "DESCARGAR VÍDEOS", br = "BAIXAR VÍDEOS", pt = "TRANSFERIR VÍDEOS", ko = "동영상 다운로드"),
    "FETCH MEDIA NOW" to Tr(ja = "いま メディアを とる", fr = "RÉCUPÉRER MAINTENANT", de = "MEDIEN JETZT LADEN", it = "SCARICA MEDIA ORA", es = "DESCARGAR MEDIOS YA", br = "BAIXAR MÍDIA AGORA", pt = "OBTER MULTIMÉDIA JÁ", ko = "지금 미디어 가져오기"),
