    "DEVELOPER" to Tr(ja = "かいはつ", fr = "DÉVELOPPEUR", de = "ENTWICKLER", it = "SVILUPPATORE", es = "DESARROLLADOR", br = "DESENVOLVEDOR", pt = "PROGRAMADOR", ko = "개발"),
    "PUBLISHER" to Tr(ja = "はんばい", fr = "ÉDITEUR", de = "PUBLISHER", it = "EDITORE", es = "EDITOR", br = "DISTRIBUIDORA", pt = "EDITORA", ko = "유통"),
    "GENRE" to Tr(ja = "ジャンル", fr = "GENRE", de = "GENRE", it = "GENERE", es = "GÉNERO", br = "GÊNERO", pt = "GÉNERO", ko = "장르"),
    "PLAYERS" to Tr(ja = "にんずう", fr = "JOUEURS", de = "SPIELER", it = "GIOCATORI", es = "JUGADORES", br = "JOGADORES", pt = "JOGADORES", ko = "인원"),
    "RATING" to Tr(ja = "ひょうか", fr = "NOTE", de = "WERTUNG", it = "VOTO", es = "NOTA", br = "NOTA", pt = "NOTA", ko = "평점"),
    "Sign in to ScreenScraper in SETTINGS for this game's box art, screenshots, video and story." to Tr(ja = "せってい で ScreenScraperに ログインすると この ゲームの パッケージ、 スクリーンショット、 どうが、 あらすじが でます。", fr = "Connectez-vous à ScreenScraper dans OPTIONS pour la jaquette, les captures, la vidéo et le résumé de ce jeu.", de = "Melde dich in OPTIONEN bei ScreenScraper an für Cover, Screenshots, Video und Story dieses Spiels.", it = "Accedi a ScreenScraper in OPZIONI per copertina, screenshot, video e trama di questo gioco.", es = "Inicia sesión en ScreenScraper en AJUSTES para la portada, capturas, vídeo e historia de este juego.", br = "Entre no ScreenScraper em CONFIG. para ver a capa, capturas, vídeo e história deste jogo.", pt = "Inicie sessão no ScreenScraper em DEFINIÇÕES para ver a capa, capturas, vídeo e história deste jogo.", ko = "설정에서 ScreenScraper에 로그인하면 이 게임의 패키지 아트, 스크린샷, 동영상, 줄거리를 볼 수 있어요."),
    "ScreenScraper has nothing for this game yet." to Tr(ja = "ScreenScraperには この ゲームの ものが まだ ありません。", fr = "ScreenScraper n'a encore rien pour ce jeu.", de = "ScreenScraper hat für dieses Spiel noch nichts.", it = "ScreenScraper non ha ancora nulla per questo gioco.", es = "ScreenScraper aún no tiene nada de este juego.", br = "O ScreenScraper ainda não tem nada deste jogo.", pt = "O ScreenScraper ainda não tem nada deste jogo.", ko = "ScreenScraper에 아직 이 게임의 정보가 없어요."),
    "From ScreenScraper" to Tr(ja = "ScreenScraperから", fr = "De ScreenScraper", de = "Von ScreenScraper", it = "Da ScreenScraper", es = "De ScreenScraper", br = "Do ScreenScraper", pt = "Do ScreenScraper", ko = "출처: ScreenScraper"),
    "Show password" to Tr(ja = "パスワードを みせる", fr = "Afficher le mot de passe", de = "Passwort zeigen", it = "Mostra password", es = "Mostrar contraseña", br = "Mostrar senha", pt = "Mostrar palavra-passe", ko = "비밀번호 보기"),
    "Hide password" to Tr(ja = "パスワードを かくす", fr = "Masquer le mot de passe", de = "Passwort verbergen", it = "Nascondi password", es = "Ocultar contraseña", br = "Ocultar senha", pt = "Ocultar palavra-passe", ko = "비밀번호 숨기기"),
    "ScreenScraper says: {0}" to Tr(ja = "ScreenScraperの こたえ: {0}", fr = "ScreenScraper répond : {0}", de = "ScreenScraper sagt: {0}", it = "ScreenScraper risponde: {0}", es = "ScreenScraper dice: {0}", br = "O ScreenScraper diz: {0}", pt = "O ScreenScraper diz: {0}", ko = "ScreenScraper 응답: {0}"),
    "ScreenScraper sent an answer the app can't read" to Tr(ja = "ScreenScraperの こたえが よめません", fr = "ScreenScraper a envoyé une réponse illisible", de = "ScreenScraper schickte eine unlesbare Antwort", it = "ScreenScraper ha inviato una risposta illeggibile", es = "ScreenScraper envió una respuesta ilegible", br = "O ScreenScraper enviou uma resposta que o app não consegue ler", pt = "O ScreenScraper enviou uma resposta que a app não consegue ler", ko = "ScreenScraper가 앱에서 읽을 수 없는 응답을 보냈어요"),
    "This build has no ScreenScraper developer login, so ScreenScraper may refuse to sign in. Release builds have one." to Tr(ja = "この ビルドには ScreenScraperの かいはつしゃ ログインが ないので ログインを ことわられることが あります。 リリース ビルドには あります。", fr = "Cette version n'a pas d'identifiant développeur ScreenScraper : la connexion peut être refusée. Les versions publiées en ont un.", de = "Diese Version hat keinen ScreenScraper-Entwicklerzugang, die Anmeldung kann abgelehnt werden. Veröffentlichte Versionen haben einen.", it = "Questa versione non ha l'accesso sviluppatore ScreenScraper, quindi l'accesso può essere rifiutato. Le versioni pubblicate ce l'hanno.", es = "Esta versión no tiene acceso de desarrollador a ScreenScraper, así que puede rechazar el inicio de sesión. Las versiones publicadas lo tienen.", br = "Esta versão não tem login de desenvolvedor do ScreenScraper, então ele pode recusar a entrada. As versões publicadas têm.", pt = "Esta versão não tem credenciais de programador do ScreenScraper, por isso pode recusar o início de sessão. As versões publicadas têm.", ko = "이 빌드에는 ScreenScraper 개발자 로그인이 없어서 로그인이 거부될 수 있어요. 정식 릴리스 빌드에는 있어요."),
    // SAVE EDITOR (a game's save, read and rearranged from the library)
    "SAVE EDITOR" to Tr(ja = "セーブ エディター", fr = "ÉDITEUR DE SAUVEGARDE", de = "SPIELSTAND-EDITOR", it = "EDITOR SALVATAGGI", es = "EDITOR DE PARTIDAS", br = "EDITOR DE SAVE", pt = "EDITOR DE GRAVAÇÕES", ko = "세이브 에디터"),
    "Change a game's boxes, bag and money" to Tr(ja = "ゲームの ボックス・バッグ・おこづかいを かえる", fr = "Modifier les boîtes, le sac et l'argent d'un jeu", de = "Boxen, Beutel und Geld eines Spiels ändern", it = "Cambia box, borsa e soldi di un gioco", es = "Cambia las cajas, la mochila y el dinero de un juego", br = "Mude as caixas, a mochila e o dinheiro de um jogo", pt = "Muda as caixas, a mochila e o dinheiro de um jogo", ko = "게임의 박스, 가방, 돈을 바꿔요"),
    "SAVE EDITOR needs a game with a save it can read: FireRed, LeafGreen, Emerald, Ruby or Sapphire, saved once in the game." to Tr(ja = "セーブ エディターには よめる セーブの ゲームが いります: ファイアレッド、 リーフグリーン、 エメラルド、 ルビー、 サファイア (ゲームで いちど セーブ)。", fr = "L'éditeur de sauvegarde demande un jeu avec une sauvegarde lisible : Rouge Feu, Vert Feuille, Émeraude, Rubis ou Saphir, sauvegardé une fois en jeu.", de = "Der Spielstand-Editor braucht ein Spiel mit lesbarem Spielstand: Feuerrot, Blattgrün, Smaragd, Rubin oder Saphir, einmal im Spiel gespeichert.", it = "L'editor salvataggi richiede un gioco con un salvataggio leggibile: Rosso Fuoco, Verde Foglia, Smeraldo, Rubino o Zaffiro, salvato una volta nel gioco.", es = "El editor de partidas necesita un juego con una partida que pueda leer: Rojo Fuego, Verde Hoja, Esmeralda, Rubí o Zafiro, guardado una vez en el juego.", br = "O editor de save precisa de um jogo com um save que ele leia: FireRed, LeafGreen, Emerald, Ruby ou Sapphire, salvo uma vez no jogo.", pt = "O editor de gravações precisa de um jogo com uma gravação que ele leia: FireRed, LeafGreen, Emerald, Ruby ou Sapphire, gravado uma vez no jogo.", ko = "세이브 에디터는 읽을 수 있는 세이브가 있는 게임이 필요해요: 파이어레드, 리프그린, 에메랄드, 루비, 사파이어 중 하나로, 게임 안에서 한 번 리포트를 쓴 것이어야 해요."),
    "The save editor reads FireRed, LeafGreen, Emerald, Ruby and Sapphire saves (and builds that keep their save layout). This game's isn't one yet." to Tr(ja = "セーブ エディターは ファイアレッド・リーフグリーン・エメラルド・ルビー・サファイアの セーブ (と おなじ かたちの セーブ)を よみます。 この ゲームの セーブには まだ たいおう していません。", fr = "L'éditeur de sauvegarde lit les sauvegardes de Rouge Feu, Vert Feuille, Émeraude, Rubis et Saphir (et des versions au même format). Pas encore celle de ce jeu.", de = "Der Spielstand-Editor liest Spielstände von Feuerrot, Blattgrün, Smaragd, Rubin und Saphir (und Versionen mit demselben Format). Den dieses Spiels noch nicht.", it = "L'editor salvataggi legge i salvataggi di Rosso Fuoco, Verde Foglia, Smeraldo, Rubino e Zaffiro (e versioni con lo stesso formato). Non ancora quello di questo gioco.", es = "El editor de partidas lee partidas de Rojo Fuego, Verde Hoja, Esmeralda, Rubí y Zafiro (y versiones con el mismo formato). Aún no la de este juego.", br = "O editor de save lê saves de FireRed, LeafGreen, Emerald, Ruby e Sapphire (e versões com o mesmo formato de save). O deste jogo ainda não.", pt = "O editor de gravações lê gravações de FireRed, LeafGreen, Emerald, Ruby e Sapphire (e versões com o mesmo formato). A deste jogo ainda não.", ko = "세이브 에디터는 파이어레드, 리프그린, 에메랄드, 루비, 사파이어의 세이브를 읽을 수 있어요 (같은 세이브 구조를 쓰는 빌드도 포함). 이 게임의 세이브는 아직 읽을 수 없어요."),
    "No save yet - save once in the game first." to Tr(ja = "セーブが まだ ありません。 さきに ゲームで いちど セーブしてください。", fr = "Pas encore de sauvegarde : sauvegardez d'abord une fois dans le jeu.", de = "Noch kein Spielstand - speichere zuerst einmal im Spiel.", it = "Nessun salvataggio: salva prima una volta nel gioco.", es = "Aún no hay partida: guarda una vez en el juego primero.", br = "Ainda não há save - salve uma vez no jogo primeiro.", pt = "Ainda não há gravação - guarde uma vez no jogo primeiro.", ko = "아직 세이브가 없어요. 먼저 게임 안에서 한 번 리포트를 쓰세요."),
    "Can't read the save {0}" to Tr(ja = "セーブ {0} を よめません", fr = "Impossible de lire la sauvegarde {0}", de = "Spielstand {0} kann nicht gelesen werden", it = "Impossibile leggere il salvataggio {0}", es = "No se puede leer la partida {0}", br = "Não é possível ler o save {0}", pt = "Não é possível ler a gravação {0}", ko = "세이브를 읽을 수 없어요: {0}"),
    "This save doesn't look like a {0} save ({1}), so it's left alone." to Tr(ja = "この セーブは {0}の セーブに みえません ({1})。 そのままに します。", fr = "Cette sauvegarde ne ressemble pas à une sauvegarde {0} ({1}) : elle n'est pas touchée.", de = "Dieser Spielstand sieht nicht nach {0} aus ({1}), er bleibt unberührt.", it = "Questo salvataggio non sembra di {0} ({1}): resta com'è.", es = "Esta partida no parece de {0} ({1}): no se toca.", br = "Este save não parece de {0} ({1}), então não será alterado.", pt = "Esta gravação não parece de {0} ({1}), por isso não é alterada.", ko = "이 세이브는 {0} 세이브로 보이지 않아서 ({1}) 그대로 두었어요."),
    "Saved. The previous save is in {0}" to Tr(ja = "セーブしました。 まえの セーブは {0} に あります", fr = "Sauvegardé. L'ancienne sauvegarde est dans {0}", de = "Gespeichert. Der vorige Spielstand liegt in {0}", it = "Salvato. Il salvataggio precedente è in {0}", es = "Guardado. La partida anterior está en {0}", br = "Salvo. O save anterior está em {0}", pt = "Guardado. A gravação anterior está em {0}", ko = "저장했어요. 이전 세이브는 {0}에 있어요"),
    "Reading the save…" to Tr(ja = "セーブを よんでいます…", fr = "Lecture de la sauvegarde…", de = "Spielstand wird gelesen…", it = "Lettura del salvataggio…", es = "Leyendo la partida…", br = "Lendo o save…", pt = "A ler a gravação…", ko = "세이브를 읽는 중…"),
    "The save changed since it was opened - open it again" to Tr(ja = "ひらいてから セーブが かわりました。 もういちど ひらいてください", fr = "La sauvegarde a changé depuis son ouverture : rouvrez-la", de = "Der Spielstand hat sich seit dem Öffnen geändert - öffne ihn erneut", it = "Il salvataggio è cambiato dopo l'apertura: riaprilo", es = "La partida cambió desde que se abrió: ábrela de nuevo", br = "O save mudou desde que foi aberto - abra de novo", pt = "A gravação mudou desde que foi aberta - abra-a de novo", ko = "연 뒤에 세이브가 바뀌었어요. 다시 열어 주세요"),
    "Can't back up the save in {0} - nothing was changed" to Tr(ja = "{0} に セーブの バックアップを つくれません。 なにも かえていません", fr = "Impossible de copier la sauvegarde dans {0} : rien n'a été modifié", de = "Kein Backup in {0} möglich - nichts wurde geändert", it = "Impossibile fare il backup in {0}: nulla è stato cambiato", es = "No se puede copiar la partida en {0}: no se cambió nada", br = "Não é possível fazer backup do save em {0} - nada foi alterado", pt = "Não é possível fazer cópia de segurança da gravação em {0} - nada foi alterado", ko = "{0}에 세이브를 백업할 수 없어요. 아무것도 바뀌지 않았어요"),
    "The save didn't read back as written - the backup was put back" to Tr(ja = "かきこんだ セーブが ただしく よめません。 バックアップを もどしました", fr = "La sauvegarde ne se relit pas comme écrite : la copie a été remise", de = "Der Spielstand ließ sich nicht wie geschrieben lesen - das Backup wurde zurückgelegt", it = "Il salvataggio non si rilegge come scritto: il backup è stato rimesso", es = "La partida no se lee como se escribió: se repuso la copia", br = "O save não foi lido como foi gravado - o backup foi restaurado", pt = "A gravação não foi lida como foi escrita - a cópia de segurança foi reposta", ko = "세이브가 쓴 대로 다시 읽히지 않아서 백업으로 되돌렸어요"),
    "Too small for a Gen 3 save ({0} bytes)" to Tr(ja = "だい3せだいの セーブには ちいさすぎます ({0} バイト)", fr = "Trop petit pour une sauvegarde de 3e génération ({0} octets)", de = "Zu klein für einen Spielstand der 3. Generation ({0} Bytes)", it = "Troppo piccolo per un salvataggio di 3ª generazione ({0} byte)", es = "Demasiado pequeño para una partida de 3.ª generación ({0} bytes)", br = "Pequeno demais para um save da Geração 3 ({0} bytes)", pt = "Pequeno demais para uma gravação da Geração 3 ({0} bytes)", ko = "3세대 세이브치고 너무 작아요 ({0}바이트)"),
    "The save is empty - save once in the game first" to Tr(ja = "セーブが からです。 さきに ゲームで いちど セーブしてください", fr = "La sauvegarde est vide : sauvegardez d'abord une fois dans le jeu", de = "Der Spielstand ist leer - speichere zuerst einmal im Spiel", it = "Il salvataggio è vuoto: salva prima una volta nel gioco", es = "La partida está vacía: guarda una vez en el juego primero", br = "O save está vazio - salve uma vez no jogo primeiro", pt = "A gravação está vazia - guarde uma vez no jogo primeiro", ko = "세이브가 비어 있어요. 먼저 게임 안에서 한 번 리포트를 쓰세요"),
    "Neither save slot is intact - the game would call this save corrupted" to Tr(ja = "どちらの セーブも こわれています。 ゲームでも よめない セーブです", fr = "Aucun des deux emplacements n'est intact : le jeu la dirait corrompue", de = "Keiner der beiden Speicherplätze ist intakt - das Spiel hielte ihn für beschädigt", it = "Nessuno dei due slot è integro: il gioco lo direbbe danneggiato", es = "Ninguna de las dos ranuras está intacta: el juego la daría por dañada", br = "Nenhum dos dois espaços de save está intacto - o jogo diria que este save está corrompido", pt = "Nenhum dos dois espaços está intacto - o jogo diria que esta gravação está corrompida", ko = "온전한 세이브 슬롯이 없어요. 게임에서는 손상된 세이브로 나와요"),
    "The save's sectors disagree on its save counter" to Tr(ja = "セーブの セクターの カウンターが あいません", fr = "Les secteurs de la sauvegarde n'ont pas le même compteur", de = "Die Sektoren des Spielstands haben verschiedene Zähler", it = "I settori del salvataggio non hanno lo stesso contatore", es = "Los sectores de la partida no tienen el mismo contador", br = "Os setores do save não concordam no contador de saves", pt = "Os setores da gravação não concordam no contador", ko = "세이브 섹터끼리 저장 횟수가 서로 달라요"),
    "Tap where it goes - any box" to Tr(ja = "おく ばしょを タッチ (どの ボックスでも)", fr = "Touchez où le mettre (n'importe quelle boîte)", de = "Tippe, wohin es soll (jede Box)", it = "Tocca dove metterlo (qualsiasi box)", es = "Toca dónde ponerlo (cualquier caja)", br = "Toque onde colocar - qualquer caixa", pt = "Toque onde colocar - qualquer caixa", ko = "옮길 곳을 탭하세요. 어느 박스든 돼요"),
    "Not saved yet" to Tr(ja = "まだ セーブしていません", fr = "Pas encore sauvegardé", de = "Noch nicht gespeichert", it = "Non ancora salvato", es = "Aún sin guardar", br = "Ainda não salvo", pt = "Ainda não guardado", ko = "아직 저장 안 됨"),
    "UNDO ALL" to Tr(ja = "ぜんぶ もどす", fr = "TOUT ANNULER", de = "ALLES ZURÜCK", it = "ANNULLA TUTTO", es = "DESHACER TODO", br = "DESFAZER TUDO", pt = "DESFAZER TUDO", ko = "모두 되돌리기"),
    "SAVE CHANGES?" to Tr(ja = "セーブ しますか?", fr = "SAUVER LES CHANGEMENTS ?", de = "ÄNDERUNGEN SICHERN?", it = "SALVARE LE MODIFICHE?", es = "¿GUARDAR LOS CAMBIOS?", br = "SALVAR AS MUDANÇAS?", pt = "GUARDAR AS ALTERAÇÕES?", ko = "변경 사항을 저장할까요?"),
    "Written the way the game saves: the save as it is now stays in the file as the game's fallback, and a copy goes to pokedaisy-backups. The game starts from the save next time, not from a resume state." to Tr(ja = "ゲームと おなじ やりかたで かきこみます: いまの セーブは ファイルの なかに ゲームの よびとして のこり、 コピーが pokedaisy-backups に はいります。 つぎは つづきの ステートでなく セーブから はじまります。", fr = "Écrit comme le jeu sauvegarde : la sauvegarde actuelle reste dans le fichier comme secours du jeu, et une copie va dans pokedaisy-backups. Le jeu repartira de la sauvegarde, pas d'un état de reprise.", de = "So geschrieben, wie das Spiel speichert: Der jetzige Spielstand bleibt als Rückfall des Spiels in der Datei, eine Kopie kommt nach pokedaisy-backups. Das Spiel startet nächstes Mal vom Spielstand, nicht von einem Fortsetzungsstand.", it = "Scritto come salva il gioco: il salvataggio attuale resta nel file come riserva del gioco e una copia va in pokedaisy-backups. Il gioco ripartirà dal salvataggio, non da uno stato di ripresa.", es = "Se escribe como guarda el juego: la partida actual queda en el archivo como respaldo del juego y una copia va a pokedaisy-backups. El juego empezará desde la partida, no desde un estado de reanudación.", br = "Gravado do jeito que o jogo salva: o save atual fica no arquivo como reserva do jogo, e uma cópia vai para pokedaisy-backups. Na próxima vez o jogo começa do save, não de um estado de retomada.", pt = "Escrito como o jogo guarda: a gravação atual fica no ficheiro como reserva do jogo, e uma cópia vai para pokedaisy-backups. Da próxima vez, o jogo começa da gravação, não de um estado de retoma.", ko = "게임이 저장하는 방식 그대로 써요: 지금의 세이브는 게임의 예비본으로 파일에 남고, 사본은 pokedaisy-backups에 들어가요. 다음에는 이어하기 스테이트가 아니라 세이브에서 게임을 시작해요."),
    "DISCARD CHANGES?" to Tr(ja = "かえた ことを すてますか?", fr = "ABANDONNER LES CHANGEMENTS ?", de = "ÄNDERUNGEN VERWERFEN?", it = "SCARTARE LE MODIFICHE?", es = "¿DESCARTAR LOS CAMBIOS?", br = "DESCARTAR AS MUDANÇAS?", pt = "DESCARTAR AS ALTERAÇÕES?", ko = "변경 사항을 버릴까요?"),
    "Your changes aren't saved. Leave without saving them?" to Tr(ja = "かえた ことは セーブ していません。 セーブせずに もどりますか?", fr = "Les changements ne sont pas sauvegardés. Quitter sans les sauver ?", de = "Die Änderungen sind nicht gespeichert. Ohne Speichern verlassen?", it = "Le modifiche non sono salvate. Uscire senza salvarle?", es = "Los cambios no están guardados. ¿Salir sin guardarlos?", br = "Suas mudanças não foram salvas. Sair sem salvar?", pt = "As alterações não foram guardadas. Sair sem guardar?", ko = "변경 사항이 저장되지 않았어요. 저장하지 않고 나갈까요?"),
    "DISCARD" to Tr(ja = "すてる", fr = "ABANDONNER", de = "VERWERFEN", it = "SCARTA", es = "DESCARTAR", br = "DESCARTAR", pt = "DESCARTAR", ko = "버리기"),
    "ID No." to Tr(ja = "IDNo.", fr = "N° ID", de = "ID-Nr.", it = "N. ID", es = "N.º ID", br = "N. ID", pt = "N. ID", ko = "IDNo."),
    "Previous box" to Tr(ja = "まえの ボックス", fr = "Boîte précédente", de = "Vorige Box", it = "Box precedente", es = "Caja anterior", br = "Caixa anterior", pt = "Caixa anterior", ko = "이전 박스"),
    "Next box" to Tr(ja = "つぎの ボックス", fr = "Boîte suivante", de = "Nächste Box", it = "Box successivo", es = "Caja siguiente", br = "Próxima caixa", pt = "Caixa seguinte", ko = "다음 박스"),
    "Tap a Pokémon to see it, then MOVE to put it in another slot." to Tr(ja = "ポケモンを タッチすると みられます。 うつす で べつの ばしょに おけます。", fr = "Touchez un Pokémon pour le voir, puis DÉPLACER pour le mettre ailleurs.", de = "Tippe auf ein Pokémon, um es zu sehen, dann VERSCHIEBEN für einen anderen Platz.", it = "Tocca un Pokémon per vederlo, poi SPOSTA per metterlo altrove.", es = "Toca un Pokémon para verlo y luego MOVER para ponerlo en otro sitio.", br = "Toque em um Pokémon para vê-lo e depois em MOVER para colocá-lo em outro espaço.", pt = "Toque num Pokémon para o ver e depois em MOVER para o pôr noutro espaço.", ko = "포켓몬을 탭해서 보고, 이동을 눌러 다른 칸으로 옮기세요."),
    "STATE" to Tr(ja = "じょうたい", fr = "ÉTAT", de = "ZUSTAND", it = "STATO", es = "ESTADO", br = "ESTADO", pt = "ESTADO", ko = "상태"),
    "BAD EGG" to Tr(ja = "ダメタマゴ", fr = "MAUVAIS ŒUF", de = "SCHLECHTES EI", it = "UOVO GUASTO", es = "HUEVO MALO", br = "OVO RUIM", pt = "OVO MAU", ko = "불량 알"),
    "EGG" to Tr(ja = "タマゴ", fr = "ŒUF", de = "EI", it = "UOVO", es = "HUEVO", br = "OVO", pt = "OVO", ko = "알"),
    "SPECIES" to Tr(ja = "しゅるい", fr = "ESPÈCE", de = "ART", it = "SPECIE", es = "ESPECIE", br = "ESPÉCIE", pt = "ESPÉCIE", ko = "종류"),
    "LEVEL" to Tr(ja = "レベル", fr = "NIVEAU", de = "LEVEL", it = "LIVELLO", es = "NIVEL", br = "NÍVEL", pt = "NÍVEL", ko = "레벨"),
    "ITEM" to Tr(ja = "もちもの", fr = "OBJET", de = "ITEM", it = "STRUMENTO", es = "OBJETO", br = "ITEM", pt = "ITEM", ko = "도구"),
    "OT" to Tr(ja = "おや", fr = "DO", de = "OT", it = "AO", es = "EO", br = "TO", pt = "TO", ko = "어버이"),
