    "BOXES" to Tr(ja = "ボックス", fr = "BOÎTES", de = "BOXEN", it = "BOX", es = "CAJAS", br = "CAIXAS", pt = "CAIXAS", ko = "박스"),
    "MONEY" to Tr(ja = "おこづかい", fr = "ARGENT", de = "GELD", it = "SOLDI", es = "DINERO", br = "DINHEIRO", pt = "DINHEIRO", ko = "돈"),
    "COINS" to Tr(ja = "コイン", fr = "JETONS", de = "MÜNZEN", it = "GETTONI", es = "FICHAS", br = "FICHAS", pt = "FICHAS", ko = "코인"),
    "ADD ITEM" to Tr(ja = "どうぐを ふやす", fr = "AJOUTER UN OBJET", de = "ITEM HINZUFÜGEN", it = "AGGIUNGI STRUMENTO", es = "AÑADIR OBJETO", br = "ADICIONAR ITEM", pt = "ADICIONAR ITEM", ko = "도구 추가"),
    "ADD MOVE" to Tr(ja = "わざを ふやす", fr = "AJOUTER UNE CAPACITÉ", de = "ATTACKE HINZUFÜGEN", it = "AGGIUNGI MOSSA", es = "AÑADIR MOVIMIENTO", br = "ADICIONAR GOLPE", pt = "ADICIONAR GOLPE", ko = "기술 추가"),
    "MIN" to Tr(ja = "MIN", fr = "MIN", de = "MIN", it = "MIN", es = "MÍN", br = "MÍN", pt = "MÍN", ko = "최소"),
    "Tap its item or a move to change it" to Tr(ja = "もちものか わざを タッチすると かえられます", fr = "Touchez son objet ou une capacité pour les changer", de = "Tippe auf Item oder Attacke, um sie zu ändern", it = "Tocca lo strumento o una mossa per cambiarli", es = "Toca su objeto o un movimiento para cambiarlo", br = "Toque no item ou em um golpe para mudá-lo", pt = "Toque no item ou num golpe para o mudar", ko = "지닌 물건이나 기술을 탭하면 바꿀 수 있어요"),
    "Key items and HMs stay as the game gave them" to Tr(ja = "だいじな ものと ひでんマシンは ゲームが くれた ままです", fr = "Objets rares et CS restent tels que le jeu les a donnés", de = "Basis-Items und VM bleiben, wie das Spiel sie gab", it = "Strumenti base e MN restano come li ha dati il gioco", es = "Los objetos clave y las MO se quedan como los dio el juego", br = "Itens-chave e MOs ficam como o jogo os deu", pt = "Itens-chave e MOs ficam como o jogo os deu", ko = "소중한 물건과 비전머신은 게임이 준 그대로 남아요"),
    // TRADE (two saves' PC boxes)
    "No other game here has a save the save editor can read" to Tr(ja = "セーブ エディターで よめる セーブの ゲームが ほかに ありません", fr = "Aucun autre jeu ici n'a une sauvegarde lisible par l'éditeur", de = "Kein anderes Spiel hier hat einen Spielstand, den der Editor lesen kann", it = "Nessun altro gioco qui ha un salvataggio leggibile dall'editor", es = "Ningún otro juego aquí tiene una partida que el editor pueda leer", br = "Nenhum outro jogo aqui tem um save que o editor consiga ler", pt = "Nenhum outro jogo aqui tem uma gravação que o editor consiga ler", ko = "세이브 에디터가 읽을 수 있는 세이브를 가진 다른 게임이 없어요"),
    "TRADE WITH" to Tr(ja = "こうかんする あいて", fr = "ÉCHANGER AVEC", de = "TAUSCHEN MIT", it = "SCAMBIA CON", es = "INTERCAMBIAR CON", br = "TROCAR COM", pt = "TROCAR COM", ko = "교환 상대"),
    "TRADE FROM" to Tr(ja = "こうかんする ゲーム", fr = "ÉCHANGER DEPUIS", de = "TAUSCHEN VON", it = "SCAMBIA DA", es = "INTERCAMBIAR DESDE", br = "TROCAR DE", pt = "TROCAR DE", ko = "보내는 쪽"),
    "TRADE SAVES" to Tr(ja = "セーブを こうかん", fr = "ÉCHANGE DE SAUVEGARDES", de = "SPIELSTÄNDE TAUSCHEN", it = "SCAMBIO TRA SALVATAGGI", es = "INTERCAMBIO DE PARTIDAS", br = "TROCA ENTRE SAVES", pt = "TROCA ENTRE GRAVAÇÕES", ko = "세이브 교환"),
    "Move Pokémon between your games' saves" to Tr(ja = "ゲームの セーブどうしで ポケモンを うごかす", fr = "Déplacer des Pokémon entre les sauvegardes de vos jeux", de = "Pokémon zwischen den Spielständen deiner Spiele bewegen", it = "Sposta Pokémon tra i salvataggi dei tuoi giochi", es = "Mueve Pokémon entre las partidas de tus juegos", br = "Mova Pokémon entre os saves dos seus jogos", pt = "Move Pokémon entre as gravações dos teus jogos", ko = "게임 세이브끼리 포켓몬을 옮겨요"),
    "TRADE SAVES needs two games with a save it can read: FireRed, LeafGreen, Emerald, Ruby or Sapphire, saved once in the game." to Tr(ja = "セーブを こうかん するには よめる セーブの ゲームが 2つ いります: ファイアレッド、 リーフグリーン、 エメラルド、 ルビー、 サファイア (ゲームで いちど セーブ)。", fr = "L'échange de sauvegardes demande deux jeux avec une sauvegarde lisible : Rouge Feu, Vert Feuille, Émeraude, Rubis ou Saphir, sauvegardés une fois en jeu.", de = "Spielstände tauschen braucht zwei Spiele mit lesbarem Spielstand: Feuerrot, Blattgrün, Smaragd, Rubin oder Saphir, einmal im Spiel gespeichert.", it = "Lo scambio tra salvataggi richiede due giochi con un salvataggio leggibile: Rosso Fuoco, Verde Foglia, Smeraldo, Rubino o Zaffiro, salvati una volta nel gioco.", es = "El intercambio de partidas necesita dos juegos con una partida que pueda leer: Rojo Fuego, Verde Hoja, Esmeralda, Rubí o Zafiro, guardados una vez en el juego.", br = "A troca entre saves precisa de dois jogos com um save que ela leia: FireRed, LeafGreen, Emerald, Ruby ou Sapphire, salvos uma vez no jogo.", pt = "A troca entre gravações precisa de dois jogos com uma gravação que ela leia: FireRed, LeafGreen, Emerald, Ruby ou Sapphire, gravados uma vez no jogo.", ko = "세이브 교환은 읽을 수 있는 세이브가 있는 게임 두 개가 필요해요: 파이어레드, 리프그린, 에메랄드, 루비, 사파이어 중에서, 게임 안에서 한 번 리포트를 쓴 것이어야 해요."),
    "Both games use the same save file" to Tr(ja = "ふたつの ゲームが おなじ セーブを つかっています", fr = "Les deux jeux utilisent la même sauvegarde", de = "Beide Spiele nutzen denselben Spielstand", it = "I due giochi usano lo stesso salvataggio", es = "Los dos juegos usan la misma partida", br = "Os dois jogos usam o mesmo arquivo de save", pt = "Os dois jogos usam o mesmo ficheiro de gravação", ko = "두 게임이 같은 세이브 파일을 쓰고 있어요"),
    "A Bad Egg can't be traded" to Tr(ja = "ダメタマゴは こうかん できません", fr = "Un Mauvais Œuf ne s'échange pas", de = "Ein schlechtes Ei kann nicht getauscht werden", it = "Un Uovo Guasto non si può scambiare", es = "Un Huevo Malo no se puede intercambiar", br = "Um Ovo Ruim não pode ser trocado", pt = "Um Ovo Mau não pode ser trocado", ko = "불량 알은 교환할 수 없어요"),
    "{0} has no National Dex yet, so no eggs" to Tr(ja = "{0}は まだ ぜんこくずかんが ないので タマゴは だめです", fr = "{0} n'a pas encore le Pokédex National : pas d'œufs", de = "{0} hat noch keinen Nationalen Pokédex: keine Eier", it = "{0} non ha ancora il Pokédex Nazionale: niente uova", es = "{0} aún no tiene la Pokédex Nacional: sin huevos", br = "{0} ainda não tem a Pokédex Nacional, então nada de ovos", pt = "{0} ainda não tem a Pokédex Nacional, por isso nada de ovos", ko = "{0}에는 아직 전국도감이 없어서 알은 교환할 수 없어요"),
    "{0} has no National Dex yet, so no {1}" to Tr(ja = "{0}は まだ ぜんこくずかんが ないので {1}は だめです", fr = "{0} n'a pas encore le Pokédex National : pas de {1}", de = "{0} hat noch keinen Nationalen Pokédex: kein {1}", it = "{0} non ha ancora il Pokédex Nazionale: niente {1}", es = "{0} aún no tiene la Pokédex Nacional: sin {1}", br = "{0} ainda não tem a Pokédex Nacional, então nada de {1}", pt = "{0} ainda não tem a Pokédex Nacional, por isso nada de {1}", ko = "{0}에는 아직 전국도감이 없어서 {1} 교환 불가"),
    "This {0} isn't from an event, so the games won't trade it" to Tr(ja = "この {0}は イベントの ポケモンでは ないので こうかん できません", fr = "Ce {0} ne vient pas d'un événement : les jeux ne l'échangent pas", de = "Dieses {0} stammt nicht von einem Event: die Spiele tauschen es nicht", it = "Questo {0} non viene da un evento: i giochi non lo scambiano", es = "Este {0} no viene de un evento: los juegos no lo intercambian", br = "Este {0} não é de um evento, então os jogos não o trocam", pt = "Este {0} não é de um evento, por isso os jogos não o trocam", ko = "이벤트 포켓몬이 아니라서 게임끼리 교환할 수 없어요: {0}"),
    "Mail and Enigma Berries stay with their save: take it off in the game first" to Tr(ja = "メールと ナゾのみは セーブに のこります。 さきに ゲームで はずしてください", fr = "Lettres et Baies Énigma restent avec leur sauvegarde : retirez-les d'abord dans le jeu", de = "Briefe und Enigmabeeren bleiben bei ihrem Spielstand: nimm sie zuerst im Spiel ab", it = "Lettere e Baccaenigma restano nel loro salvataggio: toglile prima nel gioco", es = "Las cartas y las Bayas Enigma se quedan en su partida: quítalas antes en el juego", br = "Cartas e Frutas Enigma ficam no seu save: tire-as no jogo primeiro", pt = "Cartas e Frutas Enigma ficam na sua gravação: retire-as primeiro no jogo", ko = "메일과 의문열매는 그 세이브에 남아요. 먼저 게임 안에서 빼 주세요"),
    "{0} links with Ruby, Sapphire and Emerald only after the Sevii Islands" to Tr(ja = "{0}は ナナシマの あとでないと ルビー・サファイア・エメラルドと つなげません", fr = "{0} ne se connecte à Rubis, Saphir et Émeraude qu'après les Îles Sevii", de = "{0} verbindet sich erst nach den Sevii Eilanden mit Rubin, Saphir und Smaragd", it = "{0} si collega a Rubino, Zaffiro e Smeraldo solo dopo le Isole Settipelago", es = "{0} solo conecta con Rubí, Zafiro y Esmeralda tras las Islas Sete", br = "{0} só se conecta com Ruby, Sapphire e Emerald depois das Ilhas Sevii", pt = "{0} só se liga a Ruby, Sapphire e Emerald depois das Ilhas Sevii", ko = "{0}에서는 나나섬 이후에만 루비, 사파이어, 에메랄드와 통신할 수 있어요"),
    "There's no Pokémon there" to Tr(ja = "そこに ポケモンは いません", fr = "Il n'y a pas de Pokémon ici", de = "Dort ist kein Pokémon", it = "Lì non c'è nessun Pokémon", es = "Ahí no hay ningún Pokémon", br = "Não há nenhum Pokémon aí", pt = "Não há nenhum Pokémon aí", ko = "거기에는 포켓몬이 없어요"),
    "That slot isn't empty" to Tr(ja = "その ばしょは あいていません", fr = "Cet emplacement n'est pas vide", de = "Dieser Platz ist nicht frei", it = "Quel posto non è vuoto", es = "Ese hueco no está vacío", br = "Esse espaço não está vazio", pt = "Esse espaço não está vazio", ko = "그 칸은 비어 있지 않아요"),
    "{0} goes to {1}" to Tr(ja = "{0}が {1}へ いきます", fr = "{0} part vers {1}", de = "{0} geht nach {1}", it = "{0} va in {1}", es = "{0} va a {1}", br = "{0} vai para {1}", pt = "{0} vai para {1}", ko = "{1}에 {0} 보내기"),
    "{0} for {1}" to Tr(ja = "{0}と {1}を こうかん", fr = "{0} contre {1}", de = "{0} gegen {1}", it = "{0} per {1}", es = "{0} por {1}", br = "{0} por {1}", pt = "{0} por {1}", ko = "{0}, {1} 교환"),
    "Pick a slot on each side: a Pokémon for a Pokémon, or one for an empty slot" to Tr(ja = "りょうほうで ばしょを えらんでください: ポケモンと ポケモン、 または ポケモンと あいている ばしょ", fr = "Choisissez un emplacement de chaque côté : un Pokémon contre un Pokémon, ou vers un emplacement vide", de = "Wähle auf jeder Seite einen Platz: Pokémon gegen Pokémon, oder eines auf einen freien Platz", it = "Scegli un posto per lato: un Pokémon per un Pokémon, o uno verso un posto vuoto", es = "Elige un hueco en cada lado: un Pokémon por otro, o uno a un hueco vacío", br = "Escolha um espaço de cada lado: um Pokémon por outro, ou um para um espaço vazio", pt = "Escolha um espaço de cada lado: um Pokémon por outro, ou um para um espaço vazio", ko = "양쪽에서 칸을 하나씩 고르세요: 포켓몬끼리 바꾸거나, 포켓몬을 빈칸으로 보내요"),
    "SEND" to Tr(ja = "おくる", fr = "ENVOYER", de = "SENDEN", it = "INVIA", es = "ENVIAR", br = "ENVIAR", pt = "ENVIAR", ko = "보내기"),
    "SAVE BOTH?" to Tr(ja = "りょうほう セーブ しますか?", fr = "SAUVER LES DEUX ?", de = "BEIDE SICHERN?", it = "SALVARE ENTRAMBI?", es = "¿GUARDAR AMBAS?", br = "SALVAR OS DOIS?", pt = "GUARDAR AS DUAS?", ko = "둘 다 저장할까요?"),
    "Both saves are written the way the game saves, each backed up to pokedaisy-backups first. If the second can't be written, the first is put back, so no Pokémon is lost or copied." to Tr(ja = "ふたつの セーブを ゲームと おなじ やりかたで かきこみます。 さきに それぞれを pokedaisy-backups に コピーします。 ふたつめが かけなければ ひとつめを もどすので、 ポケモンが きえたり ふえたり しません。", fr = "Les deux sauvegardes sont écrites comme le jeu sauvegarde, chacune copiée d'abord dans pokedaisy-backups. Si la seconde échoue, la première est remise : aucun Pokémon n'est perdu ni copié.", de = "Beide Spielstände werden geschrieben, wie das Spiel speichert, jeder zuerst nach pokedaisy-backups kopiert. Klappt der zweite nicht, kommt der erste zurück: kein Pokémon geht verloren oder wird verdoppelt.", it = "Entrambi i salvataggi sono scritti come salva il gioco, ognuno copiato prima in pokedaisy-backups. Se il secondo non si scrive, il primo viene rimesso: nessun Pokémon perso o copiato.", es = "Las dos partidas se escriben como guarda el juego, cada una copiada antes en pokedaisy-backups. Si la segunda falla, la primera se repone: ningún Pokémon se pierde ni se duplica.", br = "Os dois saves são gravados do jeito que o jogo salva, cada um com backup em pokedaisy-backups antes. Se o segundo não puder ser gravado, o primeiro é restaurado, então nenhum Pokémon se perde ou é copiado.", pt = "As duas gravações são escritas como o jogo guarda, cada uma com cópia de segurança em pokedaisy-backups antes. Se a segunda não puder ser escrita, a primeira é reposta, por isso nenhum Pokémon se perde nem é copiado.", ko = "두 세이브 모두 게임이 저장하는 방식으로 쓰고, 각각 먼저 pokedaisy-backups에 백업해요. 두 번째를 쓸 수 없으면 첫 번째를 되돌리니까 포켓몬이 사라지거나 복사되는 일은 없어요."),
    "The trades you made aren't saved. Leave without saving them?" to Tr(ja = "こうかんは セーブ していません。 セーブせずに もどりますか?", fr = "Les échanges ne sont pas sauvegardés. Quitter sans les sauver ?", de = "Die Tausche sind nicht gespeichert. Ohne Speichern verlassen?", it = "Gli scambi non sono salvati. Uscire senza salvarli?", es = "Los intercambios no están guardados. ¿Salir sin guardarlos?", br = "As trocas que você fez não foram salvas. Sair sem salvar?", pt = "As trocas que fez não foram guardadas. Sair sem guardar?", ko = "한 교환이 저장되지 않았어요. 저장하지 않고 나갈까요?"),
    "EVOLVING!" to Tr(ja = "しんか!", fr = "ÉVOLUTION !", de = "ENTWICKLUNG!", it = "EVOLUZIONE!", es = "¡EVOLUCIÓN!", br = "EVOLUINDO!", pt = "A EVOLUIR!", ko = "진화한다!"),
    "{0} evolves into {1} when it arrives." to Tr(ja = "{0}は とどくと {1}に しんかします。", fr = "{0} évolue en {1} à son arrivée.", de = "{0} entwickelt sich bei Ankunft zu {1}.", it = "{0} si evolve in {1} all'arrivo.", es = "{0} evoluciona a {1} al llegar.", br = "{0} evolui para {1} ao chegar.", pt = "{0} evolui para {1} ao chegar.", ko = "도착하면 {0}에서 {1}(으)로 진화해요."),
    "DON'T EVOLVE" to Tr(ja = "しんか させない", fr = "PAS D'ÉVOLUTION", de = "NICHT ENTWICKELN", it = "NON EVOLVERE", es = "NO EVOLUCIONAR", br = "NÃO EVOLUIR", pt = "NÃO EVOLUIR", ko = "진화시키지 않기"),
    // PATCH A ROM (RomPatchFlow)
    "PATCH A ROM" to Tr(ja = "ROMに パッチを あてる", fr = "PATCHER UNE ROM", de = "ROM PATCHEN", it = "PATCHA UNA ROM", es = "PARCHEAR UNA ROM", br = "APLICAR PATCH EM ROM", pt = "APLICAR PATCH A ROM", ko = "ROM 패치"),
    "APPLY PATCH" to Tr(ja = "パッチを あてる", fr = "APPLIQUER", de = "PATCH ANWENDEN", it = "APPLICA PATCH", es = "APLICAR PARCHE", br = "APLICAR PATCH", pt = "APLICAR PATCH", ko = "패치 적용"),
    "PATCH" to Tr(ja = "パッチ", fr = "PATCH", de = "PATCH", it = "PATCH", es = "PARCHE", br = "PATCH", pt = "PATCH", ko = "패치"),
    "BASE ROM" to Tr(ja = "もとの ROM", fr = "ROM DE BASE", de = "BASIS-ROM", it = "ROM DI BASE", es = "ROM BASE", br = "ROM BASE", pt = "ROM BASE", ko = "원본 ROM"),
    "PATCHED ROM" to Tr(ja = "パッチずみ ROM", fr = "ROM PATCHÉE", de = "GEPATCHTES ROM", it = "ROM PATCHATA", es = "ROM PARCHEADA", br = "ROM COM PATCH", pt = "ROM COM PATCH", ko = "패치된 ROM"),
    "MADE FOR" to Tr(ja = "たいしょう", fr = "POUR", de = "FÜR", it = "PER", es = "PARA", br = "PARA", pt = "PARA", ko = "대상"),
    "NOTES" to Tr(ja = "メモ", fr = "NOTES", de = "NOTIZEN", it = "NOTE", es = "NOTAS", br = "NOTAS", pt = "NOTAS", ko = "메모"),
    "SAVED TO" to Tr(ja = "ほぞんさき", fr = "ENREGISTRÉE DANS", de = "GESPEICHERT IN", it = "SALVATA IN", es = "GUARDADA EN", br = "SALVA EM", pt = "GUARDADA EM", ko = "저장 위치"),
    "A ROM with CRC32 {0}" to Tr(ja = "CRC32が {0}の ROM", fr = "Une ROM de CRC32 {0}", de = "Ein ROM mit CRC32 {0}", it = "Una ROM con CRC32 {0}", es = "Una ROM con CRC32 {0}", br = "Uma ROM com CRC32 {0}", pt = "Uma ROM com CRC32 {0}", ko = "CRC32 {0}인 ROM"),
    "{0} (matches)" to Tr(ja = "{0} (いっち)", fr = "{0} (correspond)", de = "{0} (passt)", it = "{0} (corrisponde)", es = "{0} (coincide)", br = "{0} (confere)", pt = "{0} (corresponde)", ko = "{0} (일치)"),
    "Reading the patch…" to Tr(ja = "パッチを よんでいます…", fr = "Lecture du patch…", de = "Patch wird gelesen…", it = "Lettura della patch…", es = "Leyendo el parche…", br = "Lendo o patch…", pt = "A ler o patch…", ko = "패치를 읽는 중…"),
    "Looking for its base ROM… {0}%" to Tr(ja = "もとの ROMを さがしています… {0}%", fr = "Recherche de la ROM de base… {0}%", de = "Suche das Basis-ROM… {0}%", it = "Cerco la ROM di base… {0}%", es = "Buscando la ROM base… {0}%", br = "Procurando a ROM base… {0}%", pt = "A procurar a ROM base… {0}%", ko = "원본 ROM을 찾는 중… {0}%"),
    "Patching… {0}%" to Tr(ja = "パッチを あてています… {0}%", fr = "Application du patch… {0}%", de = "Wird gepatcht… {0}%", it = "Applico la patch… {0}%", es = "Parcheando… {0}%", br = "Aplicando o patch… {0}%", pt = "A aplicar o patch… {0}%", ko = "패치하는 중… {0}%"),
    "BASE ROM NOT FOUND" to Tr(ja = "もとの ROMが みつかりません", fr = "ROM DE BASE INTROUVABLE", de = "BASIS-ROM NICHT GEFUNDEN", it = "ROM DI BASE NON TROVATA", es = "NO SE ENCONTRÓ LA ROM BASE", br = "ROM BASE NÃO ENCONTRADA", pt = "ROM BASE NÃO ENCONTRADA", ko = "원본 ROM 없음"),
    "This patch is for {0} (CRC32 {1}), and no ROM in your library has that checksum. Add that ROM to your library or a ROMs folder, then try again." to Tr(ja = "この パッチは {0} (CRC32 {1}) よう ですが、 ライブラリに その チェックサムの ROMが ありません。 その ROMを ライブラリか ROMフォルダに いれてから もういちど ためしてください。", fr = "Ce patch est pour {0} (CRC32 {1}), et aucune ROM de votre bibliothèque n'a cette somme de contrôle. Ajoutez cette ROM à votre bibliothèque ou à un dossier de ROM, puis réessayez.", de = "Dieser Patch ist für {0} (CRC32 {1}), und kein ROM in deiner Bibliothek hat diese Prüfsumme. Füge dieses ROM deiner Bibliothek oder einem ROM-Ordner hinzu und versuch es dann noch mal.", it = "Questa patch è per {0} (CRC32 {1}) e nessuna ROM della tua libreria ha quel checksum. Aggiungi quella ROM alla libreria o a una cartella ROM, poi riprova.", es = "Este parche es para {0} (CRC32 {1}) y ninguna ROM de tu biblioteca tiene esa suma de verificación. Añade esa ROM a tu biblioteca o a una carpeta de ROMS y vuelve a intentarlo.", br = "Este patch é para {0} (CRC32 {1}), e nenhuma ROM da sua biblioteca tem esse checksum. Adicione essa ROM à biblioteca ou a uma pasta de ROMs e tente de novo.", pt = "Este patch é para {0} (CRC32 {1}), e nenhuma ROM da sua biblioteca tem esse checksum. Adicione essa ROM à biblioteca ou a uma pasta de ROMs e tente outra vez.", ko = "이 패치는 {0}용이에요 (CRC32 {1}). 라이브러리에 그 체크섬을 가진 ROM이 없어요. 그 ROM을 라이브러리나 ROM 폴더에 추가한 뒤 다시 시도하세요."),
    "This patch is for a {0} ROM with CRC32 {1}, and no ROM in your library has that checksum. Add that ROM to your library or a ROMs folder, then try again." to Tr(ja = "この パッチは {0}で CRC32が {1}の ROMよう ですが、 ライブラリに その チェックサムの ROMが ありません。 その ROMを ライブラリか ROMフォルダに いれてから もういちど ためしてください。", fr = "Ce patch est pour une ROM de {0} au CRC32 {1}, et aucune ROM de votre bibliothèque n'a cette somme de contrôle. Ajoutez cette ROM à votre bibliothèque ou à un dossier de ROM, puis réessayez.", de = "Dieser Patch ist für ein {0}-ROM mit CRC32 {1}, und kein ROM in deiner Bibliothek hat diese Prüfsumme. Füge dieses ROM deiner Bibliothek oder einem ROM-Ordner hinzu und versuch es dann noch mal.", it = "Questa patch è per una ROM da {0} con CRC32 {1} e nessuna ROM della tua libreria ha quel checksum. Aggiungi quella ROM alla libreria o a una cartella ROM, poi riprova.", es = "Este parche es para una ROM de {0} con CRC32 {1} y ninguna ROM de tu biblioteca tiene esa suma de verificación. Añade esa ROM a tu biblioteca o a una carpeta de ROMS y vuelve a intentarlo.", br = "Este patch é para uma ROM de {0} com CRC32 {1}, e nenhuma ROM da sua biblioteca tem esse checksum. Adicione essa ROM à biblioteca ou a uma pasta de ROMs e tente de novo.", pt = "Este patch é para uma ROM de {0} com CRC32 {1}, e nenhuma ROM da sua biblioteca tem esse checksum. Adicione essa ROM à biblioteca ou a uma pasta de ROMs e tente outra vez.", ko = "이 패치는 CRC32 {1}인 {0} ROM용이에요. 라이브러리에 그 체크섬을 가진 ROM이 없어요. 그 ROM을 라이브러리나 ROM 폴더에 추가한 뒤 다시 시도하세요."),
    "Your base ROM stays as it is: the patched game is saved as a new file." to Tr(ja = "もとの ROMは そのままです。 パッチずみの ゲームは あたらしい ファイルに ほぞんされます。", fr = "Votre ROM de base ne change pas : le jeu patché est enregistré dans un nouveau fichier.", de = "Dein Basis-ROM bleibt, wie es ist: Das gepatchte Spiel wird als neue Datei gespeichert.", it = "La ROM di base resta com'è: il gioco patchato viene salvato in un nuovo file.", es = "Tu ROM base no cambia: el juego parcheado se guarda en un archivo nuevo.", br = "Sua ROM base fica como está: o jogo com patch é salvo em um arquivo novo.", pt = "A sua ROM base fica como está: o jogo com patch é guardado num ficheiro novo.", ko = "원본 ROM은 그대로 남아요. 패치된 게임은 새 파일로 저장돼요."),
    "PATCHED!" to Tr(ja = "パッチ かんりょう!", fr = "PATCHÉE !", de = "GEPATCHT!", it = "PATCHATA!", es = "¡PARCHEADA!", br = "PATCH APLICADO!", pt = "PATCH APLICADO!", ko = "패치 완료!"),
    "ALREADY PATCHED" to Tr(ja = "もう パッチずみ", fr = "DÉJÀ PATCHÉE", de = "SCHON GEPATCHT", it = "GIÀ PATCHATA", es = "YA PARCHEADA", br = "JÁ TEM O PATCH", pt = "JÁ TEM O PATCH", ko = "이미 패치됨"),
    "{0} is saved in {1}." to Tr(ja = "{0}を {1}に ほぞんしました。", fr = "{0} est enregistrée dans {1}.", de = "{0} ist in {1} gespeichert.", it = "{0} è salvata in {1}.", es = "{0} se guardó en {1}.", br = "{0} foi salva em {1}.", pt = "{0} foi guardada em {1}.", ko = "{1}에 저장했어요: {0}"),
    "This patched ROM was already in {0}, so it was kept as it is." to Tr(ja = "この パッチずみ ROMは もう {0}に あったので、 そのままに しました。", fr = "Cette ROM patchée était déjà dans {0}, elle a été gardée telle quelle.", de = "Dieses gepatchte ROM war schon in {0} und bleibt, wie es ist.", it = "Questa ROM patchata era già in {0}, quindi è rimasta com'era.", es = "Esta ROM parcheada ya estaba en {0}, así que se dejó como estaba.", br = "Esta ROM com patch já estava em {0}, então ficou como estava.", pt = "Esta ROM com patch já estava em {0}, por isso ficou como estava.", ko = "이 패치된 ROM은 이미 {0}에 있어서 그대로 두었어요."),
    "{0} is in your library." to Tr(ja = "{0}が ライブラリに はいりました。", fr = "{0} est dans votre bibliothèque.", de = "{0} ist jetzt in deiner Bibliothek.", it = "{0} è nella tua libreria.", es = "{0} está en tu biblioteca.", br = "{0} está na sua biblioteca.", pt = "{0} está na sua biblioteca.", ko = "라이브러리에 추가했어요: {0}"),
    "{0} is in your library. The second screen shows part of it." to Tr(ja = "{0}が ライブラリに はいりました。 2つめの がめんは その いちぶを ひょうじします。", fr = "{0} est dans votre bibliothèque. Le second écran en affiche une partie.", de = "{0} ist jetzt in deiner Bibliothek. Der zweite Bildschirm zeigt einen Teil davon.", it = "{0} è nella tua libreria. Il secondo schermo ne mostra una parte.", es = "{0} está en tu biblioteca. La segunda pantalla muestra una parte.", br = "{0} está na sua biblioteca. A segunda tela mostra parte dele.", pt = "{0} está na sua biblioteca. O segundo ecrã mostra parte dele.", ko = "라이브러리에 추가했어요: {0}. 두 번째 화면은 일부만 보여 줘요."),
    "{0} is in your library. The second screen doesn't know this game yet, but it can try to read it as the game it's built on." to Tr(ja = "{0}が ライブラリに はいりました。 2つめの がめんは まだ この ゲームを しりませんが、 もとの ゲームとして よんでみる ことが できます。", fr = "{0} est dans votre bibliothèque. Le second écran ne connaît pas encore ce jeu, mais il peut essayer de le lire comme le jeu sur lequel il est basé.", de = "{0} ist jetzt in deiner Bibliothek. Der zweite Bildschirm kennt dieses Spiel noch nicht, kann es aber als das Spiel lesen, auf dem es aufbaut.", it = "{0} è nella tua libreria. Il secondo schermo non conosce ancora questo gioco, ma può provare a leggerlo come il gioco su cui si basa.", es = "{0} está en tu biblioteca. La segunda pantalla aún no conoce este juego, pero puede intentar leerlo como el juego en el que se basa.", br = "{0} está na sua biblioteca. A segunda tela ainda não conhece este jogo, mas pode tentar lê-lo como o jogo em que ele se baseia.", pt = "{0} está na sua biblioteca. O segundo ecrã ainda não conhece este jogo, mas pode tentar lê-lo como o jogo em que se baseia.", ko = "라이브러리에 추가했어요: {0}. 두 번째 화면은 아직 이 게임을 모르지만, 바탕이 된 게임으로 읽어 볼 수 있어요."),
    "The second screen doesn't support {0}, so it isn't in your library." to Tr(ja = "2つめの がめんは {0}に たいおう していないので、 ライブラリには いれていません。", fr = "Le second écran ne prend pas en charge {0}, il n'est donc pas dans votre bibliothèque.", de = "Der zweite Bildschirm unterstützt {0} nicht, darum ist es nicht in deiner Bibliothek.", it = "Il secondo schermo non supporta {0}, quindi non è nella tua libreria.", es = "La segunda pantalla no es compatible con {0}, así que no está en tu biblioteca.", br = "A segunda tela não suporta {0}, então ele não está na sua biblioteca.", pt = "O segundo ecrã não suporta {0}, por isso não está na sua biblioteca.", ko = "두 번째 화면이 지원하지 않는 게임이라서 라이브러리에 넣지 않았어요: {0}"),
    "PATCH FAILED" to Tr(ja = "パッチ しっぱい", fr = "ÉCHEC DU PATCH", de = "PATCHEN FEHLGESCHLAGEN", it = "PATCH NON RIUSCITA", es = "EL PARCHE FALLÓ", br = "FALHA NO PATCH", pt = "FALHA NO PATCH", ko = "패치 실패"),
    "The patch file couldn't be read. Try picking it again." to Tr(ja = "パッチの ファイルが よめませんでした。 もういちど えらんでください。", fr = "Impossible de lire le fichier de patch. Essayez de le choisir à nouveau.", de = "Die Patch-Datei konnte nicht gelesen werden. Wähl sie noch einmal aus.", it = "Impossibile leggere il file della patch. Prova a sceglierlo di nuovo.", es = "No se pudo leer el archivo del parche. Prueba a elegirlo otra vez.", br = "Não foi possível ler o arquivo do patch. Tente escolhê-lo de novo.", pt = "Não foi possível ler o ficheiro do patch. Tente escolhê-lo outra vez.", ko = "패치 파일을 읽을 수 없어요. 다시 골라 보세요."),
    "The patched ROM couldn't be saved. Check there's free space and try again." to Tr(ja = "パッチずみ ROMを ほぞん できませんでした。 あきようりょうを たしかめて もういちど ためしてください。", fr = "Impossible d'enregistrer la ROM patchée. Vérifiez l'espace libre et réessayez.", de = "Das gepatchte ROM konnte nicht gespeichert werden. Prüf den freien Speicher und versuch es noch mal.", it = "Impossibile salvare la ROM patchata. Controlla lo spazio libero e riprova.", es = "No se pudo guardar la ROM parcheada. Comprueba que hay espacio libre y vuelve a intentarlo.", br = "Não foi possível salvar a ROM com patch. Verifique se há espaço livre e tente de novo.", pt = "Não foi possível guardar a ROM com patch. Verifique se há espaço livre e tente outra vez.", ko = "패치된 ROM을 저장할 수 없어요. 저장 공간을 확인하고 다시 시도하세요."),
    "This isn't a BPS patch. PATCH A ROM takes .bps files." to Tr(ja = "これは BPSパッチでは ありません。 ROMに パッチを あてる は .bpsファイルを つかいます。", fr = "Ce n'est pas un patch BPS. PATCHER UNE ROM prend les fichiers .bps.", de = "Das ist kein BPS-Patch. ROM PATCHEN nimmt .bps-Dateien.", it = "Questa non è una patch BPS. PATCHA UNA ROM accetta file .bps.", es = "Esto no es un parche BPS. PARCHEAR UNA ROM usa archivos .bps.", br = "Isto não é um patch BPS. APLICAR PATCH EM ROM aceita arquivos .bps.", pt = "Isto não é um patch BPS. APLICAR PATCH A ROM aceita ficheiros .bps.", ko = "BPS 패치가 아니에요. ROM 패치는 .bps 파일만 받아요."),
    "This patch file is damaged or cut short. Download it again and try once more." to Tr(ja = "この パッチの ファイルは こわれているか とちゅうで きれています。 もういちど ダウンロードして ためしてください。", fr = "Ce fichier de patch est abîmé ou incomplet. Téléchargez-le à nouveau et réessayez.", de = "Diese Patch-Datei ist beschädigt oder unvollständig. Lade sie erneut herunter und versuch es noch mal.", it = "Questo file di patch è danneggiato o incompleto. Scaricalo di nuovo e riprova.", es = "Este archivo de parche está dañado o incompleto. Descárgalo otra vez y vuelve a intentarlo.", br = "Este arquivo de patch está danificado ou incompleto. Baixe-o de novo e tente outra vez.", pt = "Este ficheiro de patch está danificado ou incompleto. Transfira-o outra vez e tente de novo.", ko = "패치 파일이 손상되었거나 잘려 있어요. 다시 다운로드해서 한 번 더 시도하세요."),
    "This patch is too big to apply on this device." to Tr(ja = "この パッチは おおきすぎて この きかいでは あてられません。", fr = "Ce patch est trop gros pour être appliqué sur cet appareil.", de = "Dieser Patch ist zu groß für dieses Gerät.", it = "Questa patch è troppo grande per questo dispositivo.", es = "Este parche es demasiado grande para este dispositivo.", br = "Este patch é grande demais para este aparelho.", pt = "Este patch é demasiado grande para este dispositivo.", ko = "이 패치는 너무 커서 이 기기에서 적용할 수 없어요."),
    "The patched ROM didn't come out right, so nothing was saved. The patch may be damaged: download it again." to Tr(ja = "パッチずみ ROMが ただしく できなかったので、 なにも ほぞんして いません。 パッチが こわれて いるかも しれません。 もういちど ダウンロードしてください。", fr = "La ROM patchée n'est pas correcte, rien n'a été enregistré. Le patch est peut-être abîmé : téléchargez-le à nouveau.", de = "Das gepatchte ROM ist nicht richtig geworden, darum wurde nichts gespeichert. Der Patch ist vielleicht beschädigt: Lade ihn erneut herunter.", it = "La ROM patchata non è venuta bene, quindi non è stato salvato nulla. La patch potrebbe essere danneggiata: scaricala di nuovo.", es = "La ROM parcheada no salió bien, así que no se guardó nada. Puede que el parche esté dañado: descárgalo otra vez.", br = "A ROM com patch não saiu certa, então nada foi salvo. O patch pode estar danificado: baixe-o de novo.", pt = "A ROM com patch não ficou correta, por isso nada foi guardado. O patch pode estar danificado: transfira-o outra vez.", ko = "패치된 ROM이 제대로 만들어지지 않아서 아무것도 저장하지 않았어요. 패치가 손상됐을 수 있어요: 다시 다운로드하세요."),
    // LINK PLAY (a game's library menu: two to four GBA games on one link cable)
    "LINK PLAY" to Tr(ja = "つうしん プレイ", fr = "JEU EN LIEN", de = "LINK-SPIEL", it = "GIOCO IN LINK", es = "JUEGO EN LINK", br = "JOGO EM LINK", pt = "JOGO EM LINK", ko = "통신 플레이"),
    "GAME {0}" to Tr(ja = "ゲーム {0}", fr = "JEU {0}", de = "SPIEL {0}", it = "GIOCO {0}", es = "JUEGO {0}", br = "JOGO {0}", pt = "JOGO {0}", ko = "게임 {0}"),
    "ADD A GAME" to Tr(ja = "ゲームを ついか", fr = "AJOUTER UN JEU", de = "SPIEL HINZUFÜGEN", it = "AGGIUNGI UN GIOCO", es = "AÑADIR JUEGO", br = "ADICIONAR JOGO", pt = "ADICIONAR JOGO", ko = "게임 추가"),
    "{0}, save {1}" to Tr(ja = "{0} セーブ {1}", fr = "{0}, sauvegarde {1}", de = "{0}, Spielstand {1}", it = "{0}, salvataggio {1}", es = "{0}, partida {1}", br = "{0}, save {1}", pt = "{0}, gravação {1}", ko = "{0}, 세이브 {1}"),
    "START LINK" to Tr(ja = "つうしん かいし", fr = "LANCER LE LIEN", de = "LINK STARTEN", it = "AVVIA IL LINK", es = "INICIAR LINK", br = "INICIAR LINK", pt = "INICIAR LINK", ko = "통신 시작"),
    "STARTING…" to Tr(ja = "かいし ちゅう…", fr = "LANCEMENT…", de = "STARTET…", it = "AVVIO…", es = "INICIANDO…", br = "INICIANDO…", pt = "A INICIAR…", ko = "시작하는 중…"),
    "No GBA games in the library yet" to Tr(ja = "ライブラリに GBAの ゲームが まだ ありません", fr = "Pas encore de jeu GBA dans la bibliothèque", de = "Noch keine GBA-Spiele in der Bibliothek", it = "Ancora nessun gioco GBA nella libreria", es = "Aún no hay juegos de GBA en la biblioteca", br = "Ainda não há jogos de GBA na biblioteca", pt = "Ainda não há jogos de GBA na biblioteca", ko = "라이브러리에 아직 GBA 게임이 없어요"),
    "Up to four GBA games run at once, joined as if by a link cable: trade, battle and mix records at the games' own Pokémon Centers. Tap a game to play it (L2 / R2 on a controller). The same game twice plays its second copy on a save of its own." to Tr(ja = "GBAの ゲームを 4つまで いっしょに うごかし つうしんケーブルで つなぎます。 ゲームの ポケモンセンターで こうかん・たいせん・レコードの まぜあわせが できます。 ゲームを タップすると あそべます (コントローラーでは L2 / R2)。 おなじ ゲームを 2つ えらぶと 2つめは べつの セーブで あそびます。", fr = "Jusqu'à quatre jeux GBA tournent ensemble, reliés comme par un câble link : échangez, combattez et mélangez les records dans les Centres Pokémon des jeux. Touchez un jeu pour y jouer (L2 / R2 à la manette). Le même jeu deux fois : la seconde copie joue sur sa propre sauvegarde.", de = "Bis zu vier GBA-Spiele laufen zusammen, wie per Link-Kabel verbunden: tauschen, kämpfen und Rekorde mischen in den Pokémon-Centern der Spiele. Tippe ein Spiel an, um es zu spielen (L2 / R2 am Controller). Dasselbe Spiel zweimal: die zweite Kopie spielt mit eigenem Spielstand.", it = "Fino a quattro giochi GBA girano insieme, collegati come da un cavo link: scambia, lotta e mescola i record nei Centri Pokémon dei giochi. Tocca un gioco per giocarci (L2 / R2 con il controller). Lo stesso gioco due volte: la seconda copia usa un salvataggio tutto suo.", es = "Hasta cuatro juegos de GBA funcionan a la vez, unidos como por un cable link: intercambia, combate y mezcla récords en los Centros Pokémon de los juegos. Toca un juego para jugarlo (L2 / R2 con mando). El mismo juego dos veces: la segunda copia usa su propia partida.", br = "Até quatro jogos de GBA rodam juntos, ligados como por um cabo link: troque, batalhe e misture recordes nos Centros Pokémon dos jogos. Toque num jogo para jogá-lo (L2 / R2 no controle). O mesmo jogo duas vezes: a segunda cópia usa um save só dela.", pt = "Até quatro jogos de GBA correm juntos, ligados como por um cabo link: troque, combata e misture recordes nos Centros Pokémon dos jogos. Toque num jogo para o jogar (L2 / R2 no comando). O mesmo jogo duas vezes: a segunda cópia usa uma gravação só sua.", ko = "GBA 게임을 최대 네 개까지 동시에 실행해서 통신 케이블로 연결한 것처럼 이어 줘요: 게임 속 포켓몬센터에서 교환, 배틀, 레코드 믹스를 할 수 있어요. 게임을 탭하면 그 게임을 플레이해요 (컨트롤러는 L2 / R2). 같은 게임을 두 번 넣으면 두 번째는 따로 된 세이브로 플레이해요."),
    "The games couldn't be started. Check that each one is a GBA game that opens on its own." to Tr(ja = "ゲームを はじめられません でした。 どれも ひとつで ひらける GBAの ゲームか たしかめて ください。", fr = "Les jeux n'ont pas pu démarrer. Vérifiez que chacun est un jeu GBA qui s'ouvre seul.", de = "Die Spiele konnten nicht starten. Prüfe, ob jedes ein GBA-Spiel ist, das sich allein öffnen lässt.", it = "I giochi non sono partiti. Controlla che ognuno sia un gioco GBA che si apre da solo.", es = "Los juegos no se pudieron iniciar. Comprueba que cada uno es un juego de GBA que se abre solo.", br = "Os jogos não puderam começar. Confira se cada um é um jogo de GBA que abre sozinho.", pt = "Os jogos não puderam começar. Verifique se cada um é um jogo de GBA que abre sozinho.", ko = "게임을 시작할 수 없어요. 각 게임이 혼자서도 열리는 GBA 게임인지 확인하세요."),
    "The link stopped. Leave and start it again; your saves are safe." to Tr(ja = "つうしんが とまりました。 いちど でて はじめなおして ください。 セーブは だいじょうぶです。", fr = "Le lien s'est arrêté. Quittez et relancez-le ; vos sauvegardes sont intactes.", de = "Der Link ist stehen geblieben. Verlasse ihn und starte neu; deine Spielstände sind sicher.", it = "Il link si è fermato. Esci e riavvialo; i tuoi salvataggi sono al sicuro.", es = "El link se ha detenido. Sal y vuelve a iniciarlo; tus partidas están a salvo.", br = "O link parou. Saia e inicie de novo; seus saves estão seguros.", pt = "O link parou. Saia e inicie de novo; as suas gravações estão seguras.", ko = "통신이 멈췄어요. 나갔다가 다시 시작하세요. 세이브는 안전해요."),
    "Tap a game to play it, or L2 / R2. BACK leaves." to Tr(ja = "ゲームを タップ か L2 / R2 で えらびます。 BACKで おわります。", fr = "Touchez un jeu pour y jouer, ou L2 / R2. RETOUR pour quitter.", de = "Tippe ein Spiel an oder nimm L2 / R2. ZURÜCK beendet.", it = "Tocca un gioco per giocarci, o L2 / R2. INDIETRO per uscire.", es = "Toca un juego para jugarlo, o L2 / R2. ATRÁS para salir.", br = "Toque num jogo para jogá-lo, ou L2 / R2. VOLTAR sai.", pt = "Toque num jogo para o jogar, ou L2 / R2. VOLTAR sai.", ko = "게임을 탭하거나 L2 / R2로 플레이해요. BACK으로 나가요."),
    "LEAVE LINK PLAY?" to Tr(ja = "つうしん プレイを おわる?", fr = "QUITTER LE JEU EN LIEN ?", de = "LINK-SPIEL BEENDEN?", it = "USCIRE DAL GIOCO IN LINK?", es = "¿SALIR DEL JUEGO EN LINK?", br = "SAIR DO JOGO EM LINK?", pt = "SAIR DO JOGO EM LINK?", ko = "통신 플레이를 끝낼까요?"),
    "Save in each game first: what you did since a game's last save is lost." to Tr(ja = "さきに どの ゲームでも セーブして ください。 さいごの セーブの あとに したことは きえます。", fr = "Sauvegardez d'abord dans chaque jeu : ce que vous avez fait depuis la dernière sauvegarde d'un jeu est perdu.", de = "Speichere zuerst in jedem Spiel: Was du seit dem letzten Speichern eines Spiels getan hast, geht verloren.", it = "Prima salva in ogni gioco: ciò che hai fatto dopo l'ultimo salvataggio di un gioco va perso.", es = "Guarda antes en cada juego: lo que hayas hecho desde la última vez que guardaste se pierde.", br = "Salve antes em cada jogo: o que você fez desde o último save de um jogo se perde.", pt = "Grave primeiro em cada jogo: o que fez desde a última gravação de um jogo perde-se.", ko = "먼저 각 게임에서 리포트를 쓰세요. 마지막 리포트 이후에 한 것은 사라져요."),
    "LEAVE" to Tr(ja = "おわる", fr = "QUITTER", de = "BEENDEN", it = "ESCI", es = "SALIR", br = "SAIR", pt = "SAIR", ko = "나가기"),
    "Finishing the games' saves…" to Tr(ja = "ゲームの セーブを おえています…", fr = "Fin des sauvegardes des jeux…", de = "Die Spielstände werden fertig geschrieben…", it = "Completamento dei salvataggi…", es = "Terminando las partidas de los juegos…", br = "Terminando os saves dos jogos…", pt = "A terminar as gravações dos jogos…", ko = "게임 세이브를 마무리하는 중…"),
)
